      <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2, flexWrap: 'wrap', rowGap: 1 }}>
        <Typography variant="h5" sx={{ fontWeight: 700 }}>Brute Force Protection Management</Typography>
        <SecurityIcon fontSize="small" />
        <InfoTooltip title="View and manage blocked IPs and affected accounts. Free entries when false positives occur." />
      </Stack>

      <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
        <Typography variant="subtitle1" sx={{ mr: 2 }}>Connection Status:</Typography>
        {connectionStatus === 'checking' && <CircularProgress size={20} sx={{ mr: 1 }} />}
        {connectionStatus === 'connected' && <CheckCircleIcon color="success" sx={{ mr: 1 }} />}
        {connectionStatus === 'disconnected' && <ErrorIcon color="error" sx={{ mr: 1 }} />}
        {connectionStatus === 'unknown' && <Typography color="text.secondary">Not checked</Typography>}
        {connectionStatus === 'disconnected' && (
          <Typography color="error.main">
            {statusMessage}
          </Typography>
        )}
        <Tooltip title="Check connection">
          <span>
            <IconButton 
              onClick={() => checkConnection(runtimeConnection)} 
              disabled={connectionStatus === 'checking' || !hasValidConnection}
              sx={{ ml: 1 }}
            >
              <RefreshIcon />
            </IconButton>
          </span>
        </Tooltip>
      </Box>

      <Paper sx={{ p: 3 }}>

        {connectionStatus === 'connected' ? (
          <>
            <Box sx={{ display: 'flex', flexDirection: { xs: 'column', sm: 'row' }, justifyContent: 'space-between', alignItems: { xs: 'stretch', sm: 'center' }, gap: 1, mb: 2 }}>
              <Typography variant="body1">
                Manage brute force protection for users and IP addresses.
              </Typography>
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, justifyContent: { xs: 'flex-start', sm: 'flex-end' } }}>
                <Button 
                  variant="outlined" 
                  color="secondary"
                  onClick={() => setOpenSearchDialog(true)}
                  size="small"
                >
                  Search & Free
                </Button>
                <Button 
                  variant="outlined" 
                  color="primary"
                  onClick={() => fetchBruteForceList(runtimeConnection)}
                  disabled={isLoadingBruteForceList}
                  startIcon={isLoadingBruteForceList ? <CircularProgress size={20} /> : <RefreshIcon />}
                  size="small"
                >
                  {isLoadingBruteForceList ? 'Loading...' : 'Refresh List'}
                </Button>
              </Box>
            </Box>

            {/* Search Box */}
            <Box sx={{ mb: 2 }}>
              <TextField
                fullWidth
                variant="outlined"
                size="small"
                placeholder="Search by IP address or username..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                InputProps={{
                  endAdornment: searchTerm && (
                    <IconButton size="small" onClick={() => setSearchTerm('')}>
                      <DeleteIcon fontSize="small" />
                    </IconButton>
                  ),
                }}
              />
            </Box>

            <Tabs 
              value={tabValue} 
              onChange={handleTabChange} 
              variant="scrollable"
              scrollButtons="auto"
              sx={{ borderBottom: 1, borderColor: 'divider' }}
            >
              <Tab label="Blocked IP Addresses" />
              <Tab label="Affected Accounts" />
            </Tabs>

            {/* Blocked IP Addresses Tab */}
            {tabValue === 0 && (
              <Box sx={{ mt: 2 }}>
                {isLoadingBruteForceList ? (
                  <LoadingIndicator />
                ) : bruteForceList && bruteForceList.blocked_ips && bruteForceList.blocked_ips.length > 0 ? (
                  <>
                    <List>
                      {filterBlockedIps(bruteForceList.blocked_ips)
                        .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                        .map((item, index) => (
                        <React.Fragment key={index}>
                          <ListItem
                            secondaryAction={
                              <Button
                                sx={{ mt: { xs: 1, sm: 0 } }}
                                variant="outlined"
                                color="secondary"
                                onClick={() => handleOpenIpDialog(item.ip_address, item.rule_name, item.protocol, item.oidc_cid)}
                                startIcon={<DeleteIcon />}
                                size="small"
                              >
                                Free
                              </Button>
                            }
                          >
                            <ListItemText
                              primary={item.ip_address}
                              secondary={
                                <>
                                  <Typography component="span" variant="body2">
                                    Rule: {item.rule_name}
                                    {item.protocol && ` | Protocol: ${item.protocol}`}
                                    {item.oidc_cid && ` | OIDC Client ID: ${item.oidc_cid}`}
                                  </Typography>
                                  <br />
                                  <Typography component="span" variant="body2">
                                    TTL: {item.ttl} seconds | Attempts: {item.attempts}
                                  </Typography>
                                </>
                              }
                            />
                          </ListItem>
                          <Divider />
                        </React.Fragment>
                      ))}
                    </List>
                    <Box display="flex" alignItems="center" justifyContent="space-between" mt={2}>
                      <TextField select size="small" label="Rows per page" value={rowsPerPage} onChange={handleChangeRowsPerPage}>
                        {rowsPerPageOptions.map((n) => <MenuItem key={n} value={n}>{n}</MenuItem>)}
                      </TextField>
                      <Pagination color="primary" page={page + 1} onChange={(_, p) => setPage(p - 1)} count={Math.max(1, Math.ceil(filterBlockedIps(bruteForceList.blocked_ips).length / rowsPerPage))} showFirstButton showLastButton />
                    </Box>
                  </>
                ) : (
                  <EmptyState 
                    message={bruteForceList === null 
                      ? 'Click "Refresh List" to load blocked IP addresses' 
                      : 'No blocked IP addresses found'} 
                  />
                )}
              </Box>
