                  ))}
                </Select>
                <FormHelperText>Select "*" to free the IP from all rules</FormHelperText>
              </FormControl>

              <TextField
                fullWidth
                label="Protocol (Optional)"
                value={selectedProtocol}
                onChange={(e) => setSelectedProtocol(e.target.value)}
                margin="normal"
                InputProps={{ endAdornment: (
                  <InputAdornment position="end"><InfoTooltip title="Optional protocol filter (e.g., smtp, imap). Leave empty for all." /></InputAdornment>
