const SystemPage = (): React.JSX.Element => {
  const { connection, loadRuntimeSettings } = useRuntime();
  const { currentProfileName, config } = useConfig();
  const [data, setData] = React.useState<MetricsResponse | null>(null);
  const [statusMessage, setStatusMessage] = React.useState<string>('');
  const [connStatus, setConnStatus] = React.useState<'unknown'|'connected'|'disconnected'|'checking'>('unknown');

  // Bootstrapping: ensure runtime settings are loaded and connection checked (debounced)
  const connectionRef = React.useRef(connection);
  React.useEffect(() => { connectionRef.current = connection; }, [connection]);
  const getConnection = React.useCallback(() => connectionRef.current, []);

  const checkConnection = React.useCallback(async (conn: any) => {
    await checkConnectionUtil(conn, setConnStatus, (msg: string) => setStatusMessage(msg));
  }, []);

  React.useEffect(() => {
    (async () => {
      try {
        await loadSettingsUtil(
          getCurrentUserId,
          loadRuntimeSettings,
          currentProfileName,
          checkConnection,
          getConnection
        );
      } catch (err) {
        console.error('Failed to load settings on SystemPage:', err);
        setStatusMessage(`Failed to load settings: ${err instanceof Error ? err.message : String(err)}`);
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentProfileName]);

  // Ensure connection check runs immediately when backend_url becomes available (bypass navigation debounce)
  React.useEffect(() => {
    if (connection?.backend_url) {
      void checkConnection(connection);
    }
  }, [connection?.backend_url, checkConnection]);

  const inFlightRef = React.useRef(false);
  const fetchMetrics = React.useCallback(async () => {
    if (inFlightRef.current) return;
    inFlightRef.current = true;
    try {
      const backendUrl = getConnection()?.backend_url;
      if (!backendUrl) return;
      const proxyUrl = new URL('/proxy/system/metrics', getProxyOrigin());
      proxyUrl.searchParams.append('url', backendUrl);

      const { authType, authValue } = prepareAuthParams(getConnection());
      if (authType && authValue) {
        proxyUrl.searchParams.append('authType', authType);
        proxyUrl.searchParams.append('authValue', authValue);
      }

      const res = await authenticatedFetch(proxyUrl.toString());
      if (!res.ok) {
        setStatusMessage(`Failed to fetch metrics: ${res.status} ${res.statusText}`);
        return;
      }
      const json = await res.json() as MetricsResponse;
      setData(json);
      setStatusMessage('');
    } catch (err) {
      console.error('Failed to fetch metrics:', err);
      setStatusMessage(`Failed to fetch metrics: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      inFlightRef.current = false;
    }
  }, [getConnection]);

  const REFRESH_SESSION_KEY = 'systemPage.refreshIntervalMs';
  const [refreshMs, setRefreshMs] = usePersistedAutoRefresh(fetchMetrics, REFRESH_SESSION_KEY, 5000);

  // Collapsible sections expanded state persisted in sessionStorage
  const getSessionBool = (key: string, def: boolean) => {
    try {
      const v = typeof window !== 'undefined' ? window.sessionStorage.getItem(key) : null;
      if (v === 'true') return true;
      if (v === 'false') return false;
    } catch {}
    return def;
  };
  const setSessionBool = (key: string, val: boolean) => {
    try { if (typeof window !== 'undefined') window.sessionStorage.setItem(key, val ? 'true' : 'false'); } catch {}
  };
  const [cpuExpanded, setCpuExpanded] = React.useState<boolean>(() => getSessionBool('ui:system:cpu', true));
  const [memoryExpanded, setMemoryExpanded] = React.useState<boolean>(() => getSessionBool('ui:system:memory', true));
  const [runtimeExpanded, setRuntimeExpanded] = React.useState<boolean>(() => getSessionBool('ui:system:runtime', true));
  const [redisExpanded, setRedisExpanded] = React.useState<boolean>(() => getSessionBool('ui:system:redis', true));
  const [detailsExpanded, setDetailsExpanded] = React.useState<boolean>(() => getSessionBool('ui:system:details', true));

  React.useEffect(() => setSessionBool('ui:system:cpu', cpuExpanded), [cpuExpanded]);
  React.useEffect(() => setSessionBool('ui:system:memory', memoryExpanded), [memoryExpanded]);
  React.useEffect(() => setSessionBool('ui:system:runtime', runtimeExpanded), [runtimeExpanded]);
  React.useEffect(() => setSessionBool('ui:system:redis', redisExpanded), [redisExpanded]);
  React.useEffect(() => setSessionBool('ui:system:details', detailsExpanded), [detailsExpanded]);

  // Prepare display values
  const version = data?.version || 'unknown';
  const instanceName = (data?.instance && data.instance.trim()) || (config?.server?.instance_name || 'nauthilus');
  const uptime = formatDuration(data?.uptime_seconds);
  const rss = formatBytes(data?.process_resident_memory_bytes);
  const alloc = formatBytes(data?.go_memstats_alloc_bytes);
  const goroutines = data?.go_goroutines ?? NaN;
  const threads = data?.go_threads ?? NaN;

  // Connections
  const connectionsCurrent = data?.connections_current;

  // Redis derived values
  const redisUp = data?.redis_up === undefined ? undefined : (data.redis_up >= 0.5);
  const redisRole = (data?.redis_role || '').trim();
  const redisClients = data?.redis_connected_clients;
  const redisMem = formatBytes(data?.redis_used_memory_bytes);
  const hits = data?.redis_keyspace_hits ?? 0;
  const misses = data?.redis_keyspace_misses ?? 0;
  const totalGets = (Number.isFinite(hits) ? hits : 0) + (Number.isFinite(misses) ? misses : 0);
  const hitRate = totalGets > 0 ? Math.round((hits / totalGets) * 100) : NaN;

  return (
    <Box>
      <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2, flexWrap: 'wrap', rowGap: 1 }}>
        <Typography variant="h5" sx={{ fontWeight: 700 }}>System</Typography><InfoTooltip title="Live metrics of this instance, fetched periodically from the backend." />
        <Chip label={`Instance: ${instanceName}`} size="small" sx={{ ml: 1 }} />
        <Chip label={`Version: ${version}`} size="small" sx={{ ml: 1 }} />
        {statusMessage && (
          <Typography variant="body2" color="text.secondary" sx={{ ml: 2 }}>{statusMessage}</Typography>
        )}
        <Box sx={{ flexGrow: 1 }} />
        <Select
          size="small"
          value={refreshMs}
          onChange={(e) => setRefreshMs(Number(e.target.value))}
          sx={{ minWidth: 120, mr: 1 }}
          displayEmpty
          aria-label="Refresh interval"
        >
          <MenuItem value={1000}>1 s</MenuItem>
          <MenuItem value={5000}>5 s</MenuItem>
          <MenuItem value={10000}>10 s</MenuItem>
          <MenuItem value={30000}>30 s</MenuItem>
          <MenuItem value={60000}>1 m</MenuItem>
          <MenuItem value={300000}>5 m</MenuItem>
        </Select>
        <Button variant="outlined" size="small" onClick={fetchMetrics}>Refresh</Button>
      </Stack>

      {/* Connection status (unified banner) */}
      <ConnectionStatus
        status={connStatus}
        message={statusMessage}
        onCheck={() => checkConnection(getConnection())}
      />

      <Grid container spacing={2}>
        <Grid size={12}>
          <Accordion
            expanded={cpuExpanded}
            onChange={() => setCpuExpanded(prev => !prev)}
          >
            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
              <Stack direction="row" spacing={1} alignItems="center">
                <Typography variant="h6" sx={{ fontWeight: 700 }}>CPU</Typography>
                <InfoTooltip title="CPU usage breakdown. User: app code; System: OS/kernel work; Nice: low‑priority work; I/O Wait: waiting for disks/network; Steal: time taken by other VMs; Idle: unused CPU. Gauges start at 0% until data arrives." />
              </Stack>
            </AccordionSummary>
            <AccordionDetails>
              <CpuUsageGauge
                user={data?.cpu_user_usage_percent}
                system={data?.cpu_system_usage_percent}
                nice={data?.cpu_nice_usage_percent}
                iowait={data?.cpu_iowait_usage_percent}
                steal={data?.cpu_steal_usage_percent}
                idle={data?.cpu_idle_usage_percent}
              />
            </AccordionDetails>
          </Accordion>
        </Grid>
        <Grid size={12}>
          <Accordion
            expanded={memoryExpanded}
            onChange={() => setMemoryExpanded(prev => !prev)}
          >
            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
              <Stack direction="row" spacing={1} alignItems="center">
                <Typography variant="h6" sx={{ fontWeight: 700 }}>Memory</Typography>
                <InfoTooltip title="Memory used by this process. RSS (Resident Set Size) is the part of memory currently in RAM; Go heap (allocated) is memory managed by Go. Values update periodically." />
              </Stack>
            </AccordionSummary>
            <AccordionDetails>
              <Grid container spacing={2}>
                <Grid size={{ xs: 12, md: 6 }}>
                  <GaugeBar
                    label="Go Heap (allocated)"
                    value={(data?.go_memstats_alloc_bytes || 0) / (1024*1024)}
                    max={1024 * 8}
                    color="info"
                    subtitle={`${alloc}`}
                  />
                </Grid>
                <Grid size={{ xs: 12, md: 6 }}>
                  <GaugeBar
                    label="Process Memory (RSS)"
                    value={(data?.process_resident_memory_bytes || 0) / (1024*1024)}
                    max={1024 * 16}
                    color="secondary"
                    subtitle={`${rss}`}
                  />
                </Grid>
              </Grid>
            </AccordionDetails>
          </Accordion>
        </Grid>
        <Grid size={12}>
          <Accordion
            expanded={runtimeExpanded}
            onChange={() => setRuntimeExpanded(prev => !prev)}
          >
            <AccordionSummary expandIcon={<ExpandMoreIcon />}> 
              <Stack direction="row" spacing={1} alignItems="center">
                <Typography variant="h6" sx={{ fontWeight: 700 }}>Runtime</Typography>
                <InfoTooltip title="General runtime stats like uptime and concurrency metrics (goroutines/threads)." />
              </Stack>
            </AccordionSummary>
            <AccordionDetails>
              <Grid container spacing={2}>
                <Grid size={{ xs: 12, md: 6 }}>
                  <StatCard icon="⏱️" title="Uptime" value={uptime} />
                </Grid>
                <Grid size={{ xs: 12, md: 6 }}>
                  <StatCard icon="📈" title="Goroutines" value={Number.isFinite(goroutines) ? String(goroutines) : 'N/A'} />
                </Grid>
                <Grid size={{ xs: 12, md: 6 }}>
                  <StatCard icon="🧵" title="Threads" value={Number.isFinite(threads) ? String(threads) : 'N/A'} />
                </Grid>
                <Grid size={{ xs: 12, md: 6 }}>
                  <StatCard icon="🔌" title="Connections" value={Number.isFinite(connectionsCurrent || NaN) ? String(connectionsCurrent) : 'N/A'} />
                </Grid>
              </Grid>
            </AccordionDetails>
          </Accordion>
        </Grid>

        <Grid size={12}>
          <Accordion
            expanded={redisExpanded}
            onChange={() => setRedisExpanded(prev => !prev)}
          >
            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
              <Stack direction="row" spacing={1} alignItems="center">
                <Typography variant="h6" sx={{ fontWeight: 700 }}>Redis</Typography>
                <InfoTooltip title="Status information for the Redis backend: Up/Down, role, connected clients, memory usage, and cache hit rate." />
              </Stack>
            </AccordionSummary>
            <AccordionDetails>
              <Grid container spacing={2}>
                <Grid size={12}>
                  <Card variant="outlined">
                    <CardContent>
                      <Stack direction="row" spacing={2} alignItems="center" flexWrap="wrap" rowGap={1}>
                        <Chip size="small" label={`Status: ${redisUp === undefined ? 'N/A' : (redisUp ? 'Up' : 'Down')}`} color={redisUp === undefined ? 'default' : (redisUp ? 'success' : 'error')} />
                        {redisRole && <Chip size="small" label={`Role: ${redisRole}`} />}
                        <Typography variant="body2" color="text.secondary">
                          Clients: {Number.isFinite(redisClients || NaN) ? String(redisClients) : 'N/A'}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          Memory: {redisMem}
                        </Typography>
                      </Stack>
                    </CardContent>
                  </Card>
                </Grid>
                <Grid size={{ xs: 12, md: 6 }}>
                  <Card variant="outlined">
                    <CardContent>
                      <Typography variant="subtitle1" sx={{ fontWeight: 'bold', mb: 1 }}>Redis Hit Rate</Typography>
                      <Box sx={{ display: 'flex', justifyContent: 'center' }}>
                        {Number.isFinite(hitRate) ? (
                          <svg width="180" height="120" viewBox="0 0 180 120" preserveAspectRatio="xMidYMid meet" aria-label="Hit Rate Gauge">
                            {(() => {
                              const value = Math.max(0, Math.min(hitRate || 0, 100));
                              const cx = 90, cy = 112, rOuter = 70, rInner = 58;
                              const baseStart = -90, totalAngle = 180, endAngle = baseStart + (totalAngle * value) / 100;
                              const toRad = (deg: number) => (deg - 90) * Math.PI / 180;
                              const polar = (ang: number, r: number) => ({ x: cx + r * Math.cos(toRad(ang)), y: cy + r * Math.sin(toRad(ang)) });
                              const arcPath = (start: number, end: number, ro: number, ri: number) => {
                                const largeArc = end - start > 180 ? 1 : 0;
                                const p1 = polar(start, ro), p2 = polar(end, ro), p3 = polar(end, ri), p4 = polar(start, ri);
                                return `M ${p1.x} ${p1.y} A ${ro} ${ro} 0 ${largeArc} 1 ${p2.x} ${p2.y} L ${p3.x} ${p3.y} A ${ri} ${ri} 0 ${largeArc} 0 ${p4.x} ${p4.y} Z`;
                              };
                              const colorFor = (val: number) => {
                                if (val >= 70) return '#4caf50';
                                if (val >= 40) return '#ff9800';
                                return '#f44336';
                              };
                              const track = arcPath(baseStart, baseStart + totalAngle, rOuter, rInner);
                              const fill = arcPath(baseStart, endAngle, rOuter, rInner);
                              return (
                                <g>
                                  <path d={track} fill="#e0e0e0" />
                                  <path d={fill} fill={colorFor(value)} />
                                  {Array.from({ length: 7 }).map((_, idx) => {
                                    const ang = baseStart + (idx * totalAngle) / 6;
                                    const po = polar(ang, rOuter);
                                    const pi = polar(ang, rOuter - 8);
                                    return <line key={idx} x1={pi.x} y1={pi.y} x2={po.x} y2={po.y} stroke="#bdbdbd" strokeWidth={1}/>;
                                  })}
                                  <text x={cx} y={cy - 14} textAnchor="middle" fontSize="16" fill="#424242">{Math.round(value)}%</text>
                                  <text x={cx} y={cy + 2} textAnchor="middle" fontSize="12" fill="#616161">Hit Rate</text>
                                </g>
                              );
                            })()}
                          </svg>
                        ) : (
                          <Typography variant="body2" color="text.secondary">No data for hit rate</Typography>
                        )}
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
              </Grid>
            </AccordionDetails>
          </Accordion>
        </Grid>

        <Grid size={12}>
          <Accordion
            expanded={detailsExpanded}
            onChange={() => setDetailsExpanded(prev => !prev)}
          >
            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
              <Typography variant="h6" sx={{ fontWeight: 700 }}>Details</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Card variant="outlined">
                <CardContent>
                  <Stack direction="row" spacing={2} alignItems="center">
                    <Typography variant="body2" color="text.secondary">
                      CPU seconds total: {data?.process_cpu_seconds_total?.toFixed ? data.process_cpu_seconds_total.toFixed(2) : 'N/A'}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      RSS (Resident Set Size): {rss} • Go heap (allocated): {alloc}
                    </Typography>
                  </Stack>
                </CardContent>
              </Card>
            </AccordionDetails>
          </Accordion>
        </Grid>
      </Grid>
    </Box>
  );
};

export default SystemPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  SelectChangeEvent,
  CircularProgress,
  Alert,
  IconButton,
  Chip,
  Avatar,
  Tooltip,
  Divider,
  Switch
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import PersonAddIcon from '@mui/icons-material/PersonAdd';
import AccountCircleIcon from '@mui/icons-material/AccountCircle';
import PhotoCameraIcon from '@mui/icons-material/PhotoCamera';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import { useUser } from '../contexts/UserContext';

const UserManagement = (): React.JSX.Element => {
  const { getUsers, addUser, removeUser, updatePassword, updateUserProfile, loading, error, clearError, user: currentUser } = useUser();
  const [users, setUsers] = useState<{
    username: string;
    roles: string[];
    displayName?: string;
    email?: string;
    avatar?: string;
    enabled?: boolean;
    lastLogin?: string | null;
    lastModified?: string;
  }[]>([]);
  const [openAddDialog, setOpenAddDialog] = useState(false);
  const [openEditDialog, setOpenEditDialog] = useState(false);
  const [openDeleteDialog, setOpenDeleteDialog] = useState(false);
  const [openProfileDialog, setOpenProfileDialog] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [email, setEmail] = useState('');
  const [avatar, setAvatar] = useState('');
  const [roles, setRoles] = useState<string[]>(['user']);
  const [selectedUser, setSelectedUser] = useState<string>('');
  const [localError, setLocalError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // File upload reference
  const fileInputRef = useRef<HTMLInputElement>(null);
  // Reference for the Add User button to restore focus
  const addUserButtonRef = useRef<HTMLButtonElement>(null);
  // One-time load guard
  const loadedRef = useRef<boolean>(false);

  // Check if the user has the admin role
  const isAdmin = currentUser?.roles.includes('admin');

  // Define loadUsers function with useCallback to memoize it
  const loadUsers = useCallback(async () => {
    const usersList = await getUsers();
    setUsers(usersList);
  }, [getUsers, setUsers]);

  // Load users once when admin is available (avoids loops and missing initial load)
  useEffect(() => {
    if (!isAdmin) return; // wait until we know the user is admin
    if (loadedRef.current) return; // only once
    loadedRef.current = true;
    (async () => {
      try {
        await loadUsers();
      } catch (e) {
        // Do not retry automatically on errors to avoid request storms
        // Errors are handled via context error state
      }
    })();
  }, [isAdmin, loadUsers]);

  const handleToggleEnabled = async (targetUsername: string, newEnabled: boolean, targetRoles: string[]) => {
    if (!isAdmin) {
      return;
    }
    // Do not allow changing own status (UI disables switch, this is an extra safety)
    if (currentUser?.username === targetUsername) {
      setLocalError('You cannot change your own status');
      await loadUsers();
      return;
    }
    // Prevent disabling the current admin user
    const isTargetCurrentAdmin = currentUser?.username === targetUsername && targetRoles.includes('admin');
    if (!newEnabled && isTargetCurrentAdmin) {
      setLocalError('Cannot disable the current admin user');
      // Reload users to reset any optimistic UI
      await loadUsers();
      return;
    }
    try {
      await updateUserProfile(targetUsername, { enabled: newEnabled });
      setSuccessMessage(`User ${targetUsername} ${newEnabled ? 'enabled' : 'disabled'} successfully`);
      await loadUsers();
    } catch (err) {
      console.error('Error toggling enabled status:', err);
      setLocalError('Failed to update user status');
      await loadUsers();
    }
  };

  const handleAddUser = async () => {
    setLocalError(null);

    // Validate input
    if (password !== confirmPassword) {
      setLocalError("Passwords don't match");
      return;
    }

    try {
      await addUser(username, password, roles);
      setOpenAddDialog(false);
      setUsername('');
      setPassword('');
      setConfirmPassword('');
      setRoles(['user']);
      setSuccessMessage('User added successfully');
      await loadUsers();

      // Restore focus to the Add User button after the dialog is closed
      setTimeout(() => {
        if (addUserButtonRef.current) {
          addUserButtonRef.current.focus();
        }
      }, 0);
    } catch (err) {
      console.error('Error adding user:', err);
    }
  };

  const handleEditUser = async () => {
    setLocalError(null);

    // Validate input
    if (password !== confirmPassword) {
      setLocalError("Passwords don't match");
      return;
    }

    try {
      await updatePassword(selectedUser, password);
      setOpenEditDialog(false);
      setPassword('');
      setConfirmPassword('');
      setSuccessMessage('Password updated successfully');
    } catch (err) {
      console.error('Error updating password:', err);
    }
  };

  const handleDeleteUser = async () => {
    // Additional validation to prevent self-deletion and ensure only admins can delete
    if (currentUser?.username === selectedUser) {
      setLocalError("You cannot delete your own account");
      setOpenDeleteDialog(false);
      return;
    }

    if (!isAdmin) {
      setLocalError("Only administrators can delete users");
      setOpenDeleteDialog(false);
      return;
    }

    try {
      await removeUser(selectedUser);
      setOpenDeleteDialog(false);
      setSuccessMessage('User deleted successfully');
      await loadUsers();
    } catch (err) {
      console.error('Error deleting user:', err);
    }
  };

  const handleRoleChange = (event: SelectChangeEvent<string[]>) => {
    const value = event.target.value;
    setRoles(typeof value === 'string' ? value.split(',') : value);
  };

  const openEdit = (username: string) => {
    setSelectedUser(username);
    setPassword('');
    setConfirmPassword('');
    setOpenEditDialog(true);
  };

  const openDelete = (username: string) => {
    setSelectedUser(username);
    setOpenDeleteDialog(true);
  };

  const openProfile = (username: string) => {
    const user = users.find(u => u.username === username);
    if (user) {
      setSelectedUser(username);
      setDisplayName(user.displayName || '');
      setEmail(user.email || '');
      setAvatar(user.avatar || '');
      // Prefill roles for profile editing; may be shown only for admins editing other users
      setRoles(Array.isArray(user.roles) ? user.roles : ['user']);
      setOpenProfileDialog(true);
    }
  };

  // Handle file upload
  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Check the file type
    if (!file.type.match('image.*')) {
      setLocalError('Please select an image file');
      return;
    }

    // Check file size (limit to 1MB)
    if (file.size > 1024 * 1024) {
      setLocalError('Image size should be less than 1MB');
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const base64String = e.target?.result as string;
      setAvatar(base64String);
    };
    reader.onerror = () => {
      setLocalError('Failed to read the image file');
    };
    reader.readAsDataURL(file);
  };

  // Trigger file input click
  const handleAvatarUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleUpdateProfile = async () => {
    setLocalError(null);

    try {
      const targetUser = users.find(u => u.username === selectedUser);
      const canEditRoles = isAdmin && currentUser?.username !== selectedUser;

      // Prevent removing the last admin
      if (canEditRoles && targetUser) {
        const currentHasAdmin = targetUser.roles.includes('admin');
        const newHasAdmin = roles.includes('admin');
        if (currentHasAdmin && !newHasAdmin) {
          const adminCount = users.filter(u => u.roles.includes('admin')).length;
          if (adminCount <= 1) {
            setLocalError('Cannot remove the last admin role');
            return;
          }
        }
      }

      const payload: any = {
        displayName: displayName || undefined,
        email: email || undefined,
        avatar: avatar || undefined
      };

      if (canEditRoles) {
        payload.roles = roles;
      }

      await updateUserProfile(selectedUser, payload);
      setOpenProfileDialog(false);
      setSuccessMessage('Profile updated successfully');
      await loadUsers();
    } catch (err) {
      console.error('Error updating profile:', err);
    }
  };

  const clearMessages = () => {
    setLocalError(null);
    clearError();
    setSuccessMessage(null);
  };

  return (
    <Box sx={{ p: 3 }}>
      {!isAdmin ? (
        // Access denied message for non-admin users
        <Alert severity="error" sx={{ mb: 2 }}>
          Access Denied: You need administrator privileges to access this page.
        </Alert>
      ) : (
        // Content only visible to admin users
        <>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
            <Typography variant="h5" component="h1">
              User Management
            </Typography>
            <Button 
              variant="contained" 
              color="primary" 
              startIcon={<PersonAddIcon />}
              onClick={() => setOpenAddDialog(true)}
              ref={addUserButtonRef}
            >
              Add User
            </Button>
          </Box>

          {error && (
            <Alert severity="error" sx={{ mb: 2 }} onClose={clearError}>
              {error}
            </Alert>
          )}

          {localError && (
            <Alert severity="error" sx={{ mb: 2 }} onClose={() => setLocalError(null)}>
              {localError}
            </Alert>
          )}

          {successMessage && (
            <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccessMessage(null)}>
              {successMessage}
            </Alert>
          )}

          {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', my: 4 }}>
              <CircularProgress />
            </Box>
          ) : (
            <TableContainer component={Paper} sx={{ width: '100%', overflowX: 'auto' }}>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>User</TableCell>
                    <TableCell>Display Name</TableCell>
                    <TableCell>Email</TableCell>
                    <TableCell>Roles</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Last Login</TableCell>
                    <TableCell>Last Modified</TableCell>
                    <TableCell align="right">Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {users.map((user) => (
                    <TableRow key={user.username}>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          {user.avatar ? (
                            <Avatar 
                              src={user.avatar} 
                              alt={user.displayName || user.username}
                              sx={{ width: 32, height: 32, mr: 1 }}
                            />
                          ) : (
                            <AccountCircleIcon sx={{ width: 32, height: 32, mr: 1 }} />
                          )}
                          {user.username}
                        </Box>
                      </TableCell>
                      <TableCell>{user.displayName || '-'}</TableCell>
                      <TableCell sx={{ wordBreak: 'break-all' }}>{user.email || '-'}</TableCell>
                      <TableCell>
                        {user.roles.map(role => (
                          <Chip 
                            key={role} 
                            label={role} 
                            color={role === 'admin' ? 'primary' : 'default'} 
                            size="small" 
                            sx={{ mr: 0.5 }} 
                          />
                        ))}
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          <Chip 
                            label={user.enabled === false ? 'Disabled' : 'Enabled'} 
                            color={user.enabled === false ? 'default' : 'success'} 
                            size="small" 
                            sx={{ mr: 1 }} 
                          />
                          {isAdmin && (
                            <Tooltip title={currentUser?.username === user.username ? 'You cannot change your own status' : 'Toggle enabled'}>
                              <span>
                                <Switch
                                  size="small"
                                  checked={user.enabled !== false}
                                  onChange={(e) => handleToggleEnabled(user.username, e.target.checked, user.roles)}
                                  disabled={!isAdmin || currentUser?.username === user.username}
                                />
                              </span>
                            </Tooltip>
                          )}
                        </Box>
                      </TableCell>
                      <TableCell>
                        {user.lastLogin !== null && user.lastLogin !== undefined ? new Date(user.lastLogin).toLocaleString() : 'Never logged in'}
                      </TableCell>
                      <TableCell>
                        {user.lastModified ? new Date(user.lastModified).toLocaleString() : '-'}
                      </TableCell>
                      <TableCell align="right">
                        <Tooltip title="Edit Password">
                          <IconButton 
                            color="primary" 
                            onClick={() => openEdit(user.username)}
                            size="small"
                          >
                            <EditIcon />
                          </IconButton>
                        </Tooltip>
                        <Tooltip title="Edit Profile">
                          <IconButton 
                            color="primary" 
                            onClick={() => openProfile(user.username)}
                            size="small"
                          >
                            <AccountCircleIcon />
                          </IconButton>
                        </Tooltip>
                        {/* Wrap the disabled button in span to allow the tooltip to work */}
                        <Tooltip title="Delete User">
                          <span>
                            <IconButton 
                              color="error" 
                              onClick={() => openDelete(user.username)}
                              size="small"
                              disabled={currentUser?.username === user.username || !isAdmin}
                            >
                              <DeleteIcon sx={{ color: (currentUser?.username === user.username || !isAdmin) ? 'action.disabled' : 'inherit' }} />
                            </IconButton>
                          </span>
                        </Tooltip>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </>
      )}

      {/* Only render dialogs if the user is admin */}
      {isAdmin && (
        <>
          {/* Add User Dialog */}
          <Dialog 
            open={openAddDialog} 
            onClose={() => {
              setOpenAddDialog(false);
              clearMessages();
              // Restore focus to the Add User button
              setTimeout(() => {
                if (addUserButtonRef.current) {
                  addUserButtonRef.current.focus();
                }
              }, 0);
            }}
            maxWidth="sm"
            fullWidth
            disableRestoreFocus
          >
            <DialogTitle>Add New User</DialogTitle>
            <DialogContent>
              <TextField
                autoFocus
                margin="dense"
                id="username"
                label="Username"
                type="text"
                fullWidth
                variant="outlined"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
                sx={{ mb: 2, mt: 1 }}
              />

              <TextField
                margin="dense"
                id="password"
                label="Password"
                type="password"
                fullWidth
                variant="outlined"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                sx={{ mb: 2 }}
              />

              <TextField
                margin="dense"
                id="confirmPassword"
                label="Confirm Password"
                type="password"
                fullWidth
                variant="outlined"
