// Admin-only toggle for enabled/disabled
// Placed at end of component file to avoid disrupting existing logic

import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import { NauthilusConfig, LuaHooksConfig } from '../types/config';
import yaml from 'js-yaml';
import axios from '../utils/axiosConfig';
import { withErrorHandling as apiWithErrorHandling, prepareAuthParams, getProxyOrigin, authenticatedFetch } from '../utils/apiUtils';

// Interface for configuration profiles
interface ConfigProfile {
  name: string;
  config: NauthilusConfig;
}

// Define the context type
interface ConfigContextType {
  config: NauthilusConfig | null;
  loading: boolean;
  error: string | null;
  hasUnsavedChanges: boolean;
  profiles: ConfigProfile[];
  currentProfileName: string;
  refreshConfig: () => Promise<void>;
  updateConfig: (config: NauthilusConfig) => Promise<void>;
  updateConfigSection: (section: string, data: any) => Promise<void>;
  uploadConfig: (file: File, profileName?: string) => Promise<void>;
  downloadConfig: () => void;
  resetConfig: () => Promise<void>;
  loadConfigFromBackend: (connectionConfig: any) => Promise<void>;
  setHasUnsavedChanges: (value: boolean) => void;
  setError: (error: string | null) => void;
  validateConfigSection: (section: string, config: NauthilusConfig) => string[];
  createProfile: (name: string, config?: NauthilusConfig) => Promise<void>;
  switchProfile: (name: string) => Promise<void>;
  renameProfile: (oldName: string, newName: string) => Promise<void>;
  deleteProfile: (name: string) => Promise<void>;
}

// Create the context with a default value
const ConfigContext = createContext<ConfigContextType | undefined>(undefined);

// Storage keys for the configuration (kept for backward compatibility)
const DEFAULT_PROFILE_NAME = 'Default';

// Helper function to get the current user ID
const getCurrentUserId = async (): Promise<string> => {
  // Always return default-user since we're storing userId-Session-Infos only in browser
  return 'default-user';
};

// Default empty configuration
const DEFAULT_CONFIG: NauthilusConfig = {
  server: {
    address: '127.0.0.1:8080',
    instance_name: 'nauthilus',
    max_concurrent_requests: 100,
    max_password_history_entries: 10,
    backends: ['cache'],
    redis: {
      database_number: 0,
      prefix: 'nt:',
      master: {
        address: '127.0.0.1:6379'
      }
    }
  }
};

// Provider component
interface ConfigProviderProps {
  children: ReactNode;
}

export const ConfigProvider = ({ children }: ConfigProviderProps): React.JSX.Element => {
  const [config, setConfig] = useState<NauthilusConfig | null>(null);
  const [profiles, setProfiles] = useState<ConfigProfile[]>([]);
  const [currentProfileName, setCurrentProfileName] = useState<string>(DEFAULT_PROFILE_NAME);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState<boolean>(false);

  // Helper function to wrap operations with error handling
  const withErrorHandling = useCallback(async <T,>(
    operation: () => Promise<T> | T,
    errorMessage: string
  ): Promise<T | undefined> => {
    return apiWithErrorHandling(setLoading, setError, operation, errorMessage);
  }, [setLoading, setError]);

  // Helper functions for validation
  const validateServerBasics = (config: NauthilusConfig, errors: string[]): void => {
    if (!config.server.address) {
      errors.push('Server address is required');
    }
    if (!config.server.instance_name) {
      errors.push('Instance name is required');
    }
    if (config.server.max_concurrent_requests === undefined || config.server.max_concurrent_requests < 1) {
      errors.push('Max concurrent requests must be at least 1');
    }
    if (config.server.max_password_history_entries === undefined || config.server.max_password_history_entries < 1) {
      errors.push('Max password history entries must be at least 1');
    }
  };

  const validateRedisConfiguration = (config: NauthilusConfig, errors: string[]): void => {
    if (!config.server.redis) {
      errors.push('Redis configuration is required');
      return;
    }

    // Determine which Redis setup type is being used
    const isMasterConfigured = config.server.redis.master && 
      (config.server.redis.master.address || 
       config.server.redis.master.username || 
       config.server.redis.master.password);

    const isReplicaConfigured = config.server.redis.replica && 
      (config.server.redis.replica.address || 
       (config.server.redis.replica.addresses && config.server.redis.replica.addresses.length > 0));

    const isSentinelConfigured = config.server.redis.sentinels && 
      (config.server.redis.sentinels.master || 
       (config.server.redis.sentinels.addresses && config.server.redis.sentinels.addresses.length > 0));

    const isClusterConfigured = config.server.redis.cluster && 
      (config.server.redis.cluster.addresses && config.server.redis.cluster.addresses.length > 0);

    // Validate the specific Redis setup type that's being configured
    if (isMasterConfigured && !config.server.redis.master?.address) {
      errors.push('Redis Master address is required when using Standalone Master configuration');
    }

    if (isReplicaConfigured && 
        !config.server.redis.replica?.address && 
        (!config.server.redis.replica?.addresses || config.server.redis.replica.addresses.length === 0)) {
      errors.push('At least one Redis Replica address is required when using Standalone Replica configuration');
    }

    if (isSentinelConfigured) {
      if (!config.server.redis.sentinels?.master) {
        errors.push('Redis Sentinel master name is required when using Sentinel configuration');
      }
      if (!config.server.redis.sentinels?.addresses || config.server.redis.sentinels.addresses.length === 0) {
        errors.push('At least one Redis Sentinel address is required when using Sentinel configuration');
      }
    }

    if (isClusterConfigured) {
      if (!config.server.redis.cluster?.addresses || config.server.redis.cluster.addresses.length === 0) {
        errors.push('At least one Redis Cluster address is required when using Cluster configuration');
      }
    }

    // Only validate that at least one type is configured if none of the specific types are being configured
    if (!isMasterConfigured && !isReplicaConfigured && !isSentinelConfigured && !isClusterConfigured) {
      errors.push('At least one Redis setup type (Master, Replica, Sentinel, or Cluster) must be configured');
    }

    // Validate Redis TLS configuration if enabled
    if (config.server.redis.tls?.enabled) {
      if (!config.server.redis.tls.cert) {
        errors.push('TLS certificate is required when Redis TLS is enabled');
      }
      if (!config.server.redis.tls.key) {
        errors.push('TLS key is required when Redis TLS is enabled');
      }
    }
  };

  const validateAuthConfigurations = (config: NauthilusConfig, errors: string[]): void => {
    // Validate basic auth configuration if enabled
    if (config.server.basic_auth?.enabled) {
      if (!config.server.basic_auth.username) {
        errors.push('Basic Auth username is required when Basic Auth is enabled');
      }
      if (!config.server.basic_auth.password) {
        errors.push('Basic Auth password is required when Basic Auth is enabled');
      } else if (config.server.basic_auth.password.length < 16) {
        errors.push('Basic Auth password must be at least 16 characters');
      }
    }

    // Validate JWT auth configuration if enabled
    if (config.server.jwt_auth?.enabled) {
      if (!config.server.jwt_auth.secret_key) {
        errors.push('JWT secret key is required when JWT Auth is enabled');
      } else if (config.server.jwt_auth.secret_key.length < 32) {
        errors.push('JWT secret key must be at least 32 characters');
      }
      if (!config.server.jwt_auth.token_expiry) {
        errors.push('JWT token expiry is required when JWT Auth is enabled');
      }
      if (config.server.jwt_auth.refresh_token && !config.server.jwt_auth.refresh_token_expiry) {
        errors.push('JWT refresh token expiry is required when refresh tokens are enabled');
      }
    }
  };

  const validateLdapConfiguration = (config: NauthilusConfig, errors: string[]): void => {
    if (config.ldap) {
      // Validate LDAP configuration
      if (!config.ldap.config.lookup_pool_size || config.ldap.config.lookup_pool_size < 1) {
        errors.push('LDAP lookup pool size must be at least 1');
      }
      if (!config.ldap.config.server_uri || config.ldap.config.server_uri.length === 0) {
        errors.push('At least one LDAP server URI is required');
      }

      // Validate search protocols if they exist
      if (config.ldap.search && config.ldap.search.length > 0) {
        config.ldap.search.forEach((search, index) => {
          if (!search.protocol || search.protocol.length === 0) {
            errors.push(`Search protocol ${index + 1} must have at least one protocol`);
          }
          if (!search.cache_name) {
            errors.push(`Search protocol ${index + 1} must have a cache name`);
          }
          if (!search.base_dn) {
            errors.push(`Search protocol ${index + 1} must have a base DN`);
          }
          if (!search.mapping.account_field) {
            errors.push(`Search protocol ${index + 1} must have an account field mapping`);
          }
          if (!search.attribute || search.attribute.length === 0) {
            errors.push(`Search protocol ${index + 1} must have at least one attribute`);
          }
        });
      }
    }
  };

  const validateLuaConfiguration = (config: NauthilusConfig, errors: string[]): void => {
    if (config.lua) {
      // Validate Lua configuration
      if (config.lua.search && config.lua.search.length > 0) {
        config.lua.search.forEach((search, index) => {
          if (!search.protocol || search.protocol.length === 0) {
            errors.push(`Lua search protocol ${index + 1} must have at least one protocol`);
          }
          if (!search.cache_name) {
            errors.push(`Lua search protocol ${index + 1} must have a cache name`);
          }
        });
      }
    }
  };

  // Function to validate the configuration
  const validateConfig = useCallback((config: NauthilusConfig): string[] => {
    const errors: string[] = [];

    // Validate server configuration
    validateServerBasics(config, errors);

    // Validate that at least one backend is configured
    if (!config.server.backends || config.server.backends.length === 0) {
      errors.push('At least one backend must be configured');
    }

    // Validate Redis configuration
    validateRedisConfiguration(config, errors);

    // Validate auth configurations
    validateAuthConfigurations(config, errors);

    return errors;
  }, []);

  // Function to validate a specific section of the configuration
  const validateConfigSection = useCallback((section: string, config: NauthilusConfig): string[] => {
    const errors: string[] = [];

    switch (section) {
      case 'server':
        // Validate server configuration
        validateServerBasics(config, errors);
        validateRedisConfiguration(config, errors);
        validateAuthConfigurations(config, errors);
        break;

      case 'ldap':
        validateLdapConfiguration(config, errors);
        break;

      case 'lua':
        validateLuaConfiguration(config, errors);
        break;

      default:
        // For other sections, use the general validation
        errors.push(...validateConfig(config));
        break;
    }

    return errors;
  }, [validateConfig]);

  // Function to load the configuration profiles from MongoDB
  const refreshConfig = useCallback(async () => {
    await withErrorHandling(async () => {
      const userId = await getCurrentUserId();
      let profilesArray: ConfigProfile[];
      let currentProfile: string;

      try {
        // Try to load from API
        const response = await axios.get(`/api/profiles/${userId}`);
        profilesArray = response.data.profiles;
        currentProfile = response.data.currentProfileName;
      } catch (error) {
        console.log('Failed to load from API, creating default profile:', error);

        // Create a default profile if none exists
        profilesArray = [{ name: DEFAULT_PROFILE_NAME, config: DEFAULT_CONFIG }];
        currentProfile = DEFAULT_PROFILE_NAME;

        // Save to API for future use
        try {
          await axios.post(`/api/profiles/${userId}`, {
            profiles: profilesArray,
            currentProfileName: currentProfile
          });
          console.log('Created default profile in MongoDB');
        } catch (saveError) {
          console.error('Failed to save default profiles to API:', saveError);
          throw new Error('Failed to initialize profiles in MongoDB');
        }
      }

      // Make sure the current profile exists in the profiles-array
      if (!profilesArray.some(profile => profile.name === currentProfile)) {
        currentProfile = profilesArray.length > 0 ? profilesArray[0].name : DEFAULT_PROFILE_NAME;
      }

      setProfiles(profilesArray);
      setCurrentProfileName(currentProfile);

      // Set the current config
      const profileConfig = profilesArray.find(profile => profile.name === currentProfile)?.config;
      setConfig(profileConfig || null);

      return profilesArray;
    }, 'Failed to load configuration profiles. Please try again.');
  }, [withErrorHandling, setProfiles, setCurrentProfileName, setConfig]);

  // Helper function to update profiles with a new config
  const updateProfilesWithConfig = useCallback(async (newConfig: NauthilusConfig) => {
    const updatedProfiles = profiles.map(profile => 
      profile.name === currentProfileName 
        ? { ...profile, config: newConfig } 
        : profile
    );

    // Update in MongoDB
    const userId = await getCurrentUserId();
    try {
      await axios.post(`/api/profiles/${userId}`, {
        profiles: updatedProfiles,
        currentProfileName: currentProfileName
      });
    } catch (error) {
      console.error('Failed to save profiles to API:', error);
      throw new Error('Failed to save profiles to MongoDB');
    }

    setProfiles(updatedProfiles);
    setConfig(newConfig);

    // Reset the unsaved changes flag since we've just saved
    setHasUnsavedChanges(false);

    return updatedProfiles;
  }, [profiles, currentProfileName, setProfiles, setConfig, setHasUnsavedChanges]);

  // Function to update the entire configuration
  const updateConfig = useCallback(async (newConfig: NauthilusConfig) => {
    await withErrorHandling(
      async () => await updateProfilesWithConfig(newConfig),
      'Failed to update configuration. Please try again.'
    );
  }, [withErrorHandling, updateProfilesWithConfig]);

  // Function to update a specific section of the configuration
  const updateConfigSection = useCallback(async (section: string, data: any) => {
    await withErrorHandling(async () => {
      if (!config) {
        throw new Error('No configuration loaded');
      }

      // Create a new config object with the updated section
      const newConfig = { ...config };

      // Merge the new data with the existing data instead of replacing it entirely
      (newConfig as any)[section] = {
        ...(newConfig as any)[section],
        ...data
      };

      // Validate the configuration before saving
      const validationErrors = validateConfigSection(section, newConfig);
      if (validationErrors.length > 0) {
        throw new Error(`Validation failed: ${validationErrors.join(', ')}`);
      }

      return await updateProfilesWithConfig(newConfig);
    }, `Failed to update ${section} configuration. Please try again.`);
  }, [withErrorHandling, config, updateProfilesWithConfig, validateConfigSection]);

  // Helper function to filter out unknown settings
  const filterUnknownSettings = (config: NauthilusConfig): NauthilusConfig => {
    // Create a new config object with only the known properties
    const filteredConfig: NauthilusConfig = {
      server: {
        redis: { database_number: 0, prefix: 'nt:' }
      }
    };

    // Copy known server properties
    if (config.server) {
      const serverProps = [
        'address', 'max_concurrent_requests', 'max_password_history_entries',
        'http3', 'haproxy_v2', 'disabled_endpoints', 'tls', 'basic_auth',
        'jwt_auth', 'instance_name', 'log', 'backends', 'features',
        'brute_force_protocols', 'ory_hydra_admin_url', 'dns', 'insights',
        'redis', 'master_user', 'frontend', 'prometheus_timer',
        'default_http_request_header', 'http_client', 'compression', 'keep_alive',
        'dedup', 'timeouts'
      ];

      serverProps.forEach(prop => {
        const key = prop as keyof typeof config.server;
        if (config.server[key] !== undefined) {
          // Use type assertion to help TypeScript understand the assignment
          (filteredConfig.server as any)[key] = config.server[key];
        }
      });
    }

    // Copy other known top-level properties
    const knownProps = [
      'ldap', 'lua', 'oauth2', 'brute_force', 'realtime_blackhole_lists',
      'relay_domains', 'backend_server_monitoring', 'cleartext_networks'
    ];

    knownProps.forEach(prop => {
      const key = prop as keyof NauthilusConfig;
      if (config[key] !== undefined) {
        // Use type assertion to help TypeScript understand the assignment
        (filteredConfig as any)[key] = config[key];
      }
    });

    return filteredConfig;
  };

  // Helper function to initialize feature configurations
  const initializeFeatureConfigurations = (config: NauthilusConfig): NauthilusConfig => {
    const newConfig = { ...config };

    if (newConfig.server?.features) {
      // Handle RBL configuration
      if (newConfig.server.features.includes('rbl')) {
        // Initialize RBL configuration if it doesn't exist
        if (!newConfig.realtime_blackhole_lists) {
          newConfig.realtime_blackhole_lists = {
            lists: [],
            threshold: 0,
            ip_whitelist: [],
            soft_whitelist: {}
          };
        }

        // Ensure the "lists" array is properly initialized
        if (!newConfig.realtime_blackhole_lists.lists) {
          newConfig.realtime_blackhole_lists.lists = [];
        }

        // Ensure the ip_whitelist array is properly initialized
        if (!newConfig.realtime_blackhole_lists.ip_whitelist) {
          newConfig.realtime_blackhole_lists.ip_whitelist = [];
        }

        // Ensure the soft_whitelist object is properly initialized
        if (!newConfig.realtime_blackhole_lists.soft_whitelist) {
          newConfig.realtime_blackhole_lists.soft_whitelist = {};
        }
      }

      // Handle Relay Domains configuration
      if (newConfig.server.features.includes('relay_domains')) {
        // Initialize Relay Domains configuration if it doesn't exist
        if (!newConfig.relay_domains) {
          newConfig.relay_domains = {
            static: [],
            soft_whitelist: {}
          };
        }

        // Ensure the static array is properly initialized
        if (!newConfig.relay_domains.static) {
          newConfig.relay_domains.static = [];
        }

        // Ensure the soft_whitelist object is properly initialized
        if (!newConfig.relay_domains.soft_whitelist) {
          newConfig.relay_domains.soft_whitelist = {};
        }
      }

      // Handle Backend Server Monitoring configuration
      if (newConfig.server.features.includes('backend_server_monitoring')) {
        // Initialize Backend Server Monitoring configuration if it doesn't exist
        if (!newConfig.backend_server_monitoring) {
          newConfig.backend_server_monitoring = {
            backend_servers: []
          };
        }

        // Ensure the backend_servers array is properly initialized
        if (!newConfig.backend_server_monitoring.backend_servers) {
          newConfig.backend_server_monitoring.backend_servers = [];
        }
      }

      // Handle Brute Force configuration
      if (newConfig.server.features.includes('brute_force')) {
        // Initialize Brute Force configuration if it doesn't exist
        if (!newConfig.brute_force) {
          newConfig.brute_force = {
            buckets: [],
            ip_whitelist: [],
            soft_whitelist: {},
            custom_tolerations: []
          };
        }

        // Ensure the "buckets" array is properly initialized
        if (!newConfig.brute_force.buckets) {
          newConfig.brute_force.buckets = [];
        }

        // Ensure the ip_whitelist array is properly initialized
        if (!newConfig.brute_force.ip_whitelist) {
          newConfig.brute_force.ip_whitelist = [];
        }

        // Ensure the soft_whitelist object is properly initialized
        if (!newConfig.brute_force.soft_whitelist) {
          newConfig.brute_force.soft_whitelist = {};
        }

        // Ensure the custom_tolerations array is properly initialized
        if (!newConfig.brute_force.custom_tolerations) {
          newConfig.brute_force.custom_tolerations = [];
        }
      }

      // Handle TLS Encryption configuration
      if (newConfig.server.features.includes('tls_encryption')) {
        // Ensure the cleartext_networks array is properly initialized
        if (!newConfig.cleartext_networks) {
          newConfig.cleartext_networks = [];
        }
      }
    }

    return newConfig;
  };

  // Function to upload a configuration file
  const uploadConfig = useCallback(async (file: File, profileName?: string) => {
    await withErrorHandling(async () => {
      const fileContent = await file.text();
      let newConfig: NauthilusConfig;

      // Parse the file content based on the file extension
      if (file.name.endsWith('.json')) {
        newConfig = JSON.parse(fileContent);
      } else if (file.name.endsWith('.yml') || file.name.endsWith('.yaml')) {
        newConfig = yaml.load(fileContent) as NauthilusConfig;

        // Handle realtime_blackhole_lists (map to rbl)
        if ((newConfig as any).realtime_blackhole_lists) {
          newConfig.realtime_blackhole_lists = (newConfig as any).realtime_blackhole_lists;
          delete (newConfig as any).realtime_blackhole_lists;

          // Ensure server.features includes 'rbl'
          if (!newConfig.server) {
            newConfig.server = { redis: { database_number: 0, prefix: 'nt_', master: { address: '127.0.0.1:6379' } } };
          }
          if (!newConfig.server.features) {
            newConfig.server.features = [];
          }
          if (!newConfig.server.features.includes('rbl')) {
            newConfig.server.features.push('rbl');
          }
        }

        // Fix the backend configuration format if it's an array of objects with the 'backend' property
        if (newConfig.server?.backends && Array.isArray(newConfig.server.backends)) {
          // Check if the backends are objects with 'backend' property instead of strings
          const firstBackend = newConfig.server.backends[0];
          if (firstBackend && typeof firstBackend === 'object' && 'backend' in firstBackend) {
            // Convert objects with 'backend' property to strings
            newConfig.server.backends = newConfig.server.backends.map((backend: any) => backend.backend);
          }
        }

        // Filter out unknown settings
        newConfig = filterUnknownSettings(newConfig);

        // Initialize feature configurations
        newConfig = initializeFeatureConfigurations(newConfig);
      } else {
        throw new Error('Unsupported file format. Please upload a JSON or YAML file.');
      }

      // Determine which profile to update
      const targetProfileName = profileName || currentProfileName;

      // Check if the profile exists
      let updatedProfiles = [...profiles];
      const profileIndex = updatedProfiles.findIndex(p => p.name === targetProfileName);

      if (profileIndex >= 0) {
        // Update existing profile
        updatedProfiles[profileIndex] = {
          ...updatedProfiles[profileIndex],
          config: newConfig
        };
      } else {
        // Create a new profile if it doesn't exist
        updatedProfiles.push({
          name: targetProfileName,
          config: newConfig
        });
      }

      // Save profiles to MongoDB
      const userId = await getCurrentUserId();
      try {
        await axios.post(`/api/profiles/${userId}`, {
          profiles: updatedProfiles,
          currentProfileName: targetProfileName === currentProfileName ? currentProfileName : targetProfileName
        });
      } catch (error) {
        console.error('Failed to save profiles to API:', error);
        throw new Error('Failed to save profiles to MongoDB');
      }

      setProfiles(updatedProfiles);

      // If updating the current profile, update the current config
      if (targetProfileName === currentProfileName) {
        setConfig(newConfig);
      } else {
        // Switch to the new/updated profile
        setCurrentProfileName(targetProfileName);
        setConfig(newConfig);
      }

      // Reset the unsaved changes flag since we've just saved
      setHasUnsavedChanges(false);

      return updatedProfiles;
    }, 'Failed to upload configuration. Please check the file format.');
  }, [withErrorHandling, profiles, currentProfileName, setProfiles, setCurrentProfileName, setConfig, setHasUnsavedChanges]);

  // Function to download the current configuration
  const downloadConfig = useCallback(() => {
    // This function doesn't use async/await, so we'll handle errors manually
    try {
      if (!config) {
        setError('No configuration to download');
        return;
      }

      // Check if there are unsaved changes
      if (hasUnsavedChanges) {
        setError('Please save your changes before downloading the configuration.');
        return;
      }

      // Validate required fields before allowing download
      const validationErrors = validateConfig(config);
      if (validationErrors.length > 0) {
        setError(`Cannot download configuration: ${validationErrors.join(', ')}`);
        return;
      }

      // Create a deep copy of the configuration to ensure all nested objects are included
      const configToDownload = JSON.parse(JSON.stringify(config));

      // Exclude connection and hooks settings from the download
      delete configToDownload.connection;
      if (configToDownload.lua && configToDownload.lua.hooks) {
        delete configToDownload.lua.hooks;
      }

      // Add a profile name as a comment in the YAML
      const profileComment = `# Profile: ${currentProfileName}`;

      // Ensure brute_force_protocols are lowercase
      if (configToDownload.server?.brute_force_protocols) {
        configToDownload.server.brute_force_protocols = configToDownload.server.brute_force_protocols.map((protocol: string) => 
          protocol.toLowerCase()
        );
      }

      // Ensure refresh_token_expiry is set if refresh_token is enabled
      if (configToDownload.server?.jwt_auth?.refresh_token && !configToDownload.server.jwt_auth.refresh_token_expiry) {
        if (!configToDownload.server.jwt_auth) {
          configToDownload.server.jwt_auth = {};
        }
        configToDownload.server.jwt_auth.refresh_token_expiry = '24h'; // Default value
      }

      // Convert the configuration to YAML
      const yamlContent = yaml.dump(configToDownload);

      // Create a blob and download the link with the profile comment at the top
      const contentWithComment = `${profileComment}\n\n${yamlContent}`;
      const blob = new Blob([contentWithComment], { type: 'text/yaml' });
      const url = URL.createObjectURL(blob);

      const a = document.createElement('a');
      a.href = url;
      a.download = `nauthilus-${currentProfileName.toLowerCase().replace(/\s+/g, '-')}.yml`;
      document.body.appendChild(a);
      a.click();

      // Clean up
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      setError('Failed to download configuration.');
      console.error('Error downloading configuration:', err);
    }
  }, [config, hasUnsavedChanges, validateConfig, currentProfileName, setError]);

  // Function to reset the configuration to default
  const resetConfig = useCallback(async () => {
    // Reset only the current profile by default
    await withErrorHandling(
      () => updateProfilesWithConfig(DEFAULT_CONFIG),
      'Failed to reset configuration. Please try again.'
    );
  }, [withErrorHandling, updateProfilesWithConfig]);

  // Function to create a new profile
  const createProfile = useCallback(async (name: string, configData?: NauthilusConfig) => {
    await withErrorHandling(async () => {
      // Check if the profile with this name already exists
      if (profiles.some(profile => profile.name === name)) {
        throw new Error(`A profile with the name "${name}" already exists.`);
      }

      // Create new profile with provided config or default
      const newProfile: ConfigProfile = {
        name,
        config: configData || DEFAULT_CONFIG
      };

      // Add a new profile to the list
      const updatedProfiles = [...profiles, newProfile];

      // Save to MongoDB
      const userId = await getCurrentUserId();
      try {
        await axios.post(`/api/profiles/${userId}`, {
          profiles: updatedProfiles,
          currentProfileName: name
        });
      } catch (error) {
        console.error('Failed to save profiles to API:', error);
        throw new Error('Failed to save profiles to MongoDB');
      }

      setProfiles(updatedProfiles);

      // Switch to the new profile
      setCurrentProfileName(name);
      setConfig(newProfile.config);
      setHasUnsavedChanges(false);

      return updatedProfiles;
    }, 'Failed to create profile. Please try again.');
  }, [withErrorHandling, profiles, setProfiles, setCurrentProfileName, setConfig, setHasUnsavedChanges]);

  // Function to switch to a different profile
  const switchProfile = useCallback(async (name: string) => {
    await withErrorHandling(async () => {
      // Find the profile
      const profile = profiles.find(p => p.name === name);
      if (!profile) {
        throw new Error(`Profile "${name}" not found.`);
      }

      // Check for unsaved changes
      if (hasUnsavedChanges) {
        throw new Error('Please save your changes before switching profiles.');
      }

      // Switch to the profile
      setCurrentProfileName(name);
      setConfig(profile.config);

      // Save to MongoDB
      const userId = await getCurrentUserId();
      try {
        await axios.post(`/api/profiles/${userId}`, {
          profiles,
          currentProfileName: name
        });
      } catch (error) {
        console.error('Failed to save current profile to API:', error);
        throw new Error('Failed to save current profile to MongoDB');
      }

      setHasUnsavedChanges(false);

      return profile;
    }, 'Failed to switch profile. Please try again.');
  }, [withErrorHandling, profiles, hasUnsavedChanges, setCurrentProfileName, setConfig, setHasUnsavedChanges]);

  // Function to rename a profile
  const renameProfile = useCallback(async (oldName: string, newName: string) => {
    await withErrorHandling(async () => {
      // Check if a new name already exists
      if (profiles.some(profile => profile.name === newName)) {
        throw new Error(`A profile with the name "${newName}" already exists.`);
      }

      // Find and rename the profile
      const updatedProfiles = profiles.map(profile => 
        profile.name === oldName 
          ? { ...profile, name: newName } 
          : profile
      );

      // Save to MongoDB
      const userId = await getCurrentUserId();
      try {
        await axios.post(`/api/profiles/${userId}`, {
          profiles: updatedProfiles,
          currentProfileName: currentProfileName === oldName ? newName : currentProfileName
        });

        // Update runtime settings reference to the profile
        try {
          // First, get the current runtime settings for the old profile name
          const runtimeResponse = await axios.get(`/api/runtime/${userId}/${oldName}`);
          const { connection, hooks } = runtimeResponse.data;

          // Save the runtime settings with the new profile name
          await axios.post(`/api/runtime/${userId}/${newName}`, {
            connection,
            hooks
          });

          // Delete the old runtime settings
          try {
            await axios.delete(`/api/runtime/${userId}/${oldName}`);
            console.log(`Old runtime settings deleted for profile "${oldName}"`);
          } catch (deleteError) {
            console.warn(`Failed to delete old runtime settings for profile "${oldName}":`, deleteError);
            // Don't throw an error here, as the profile rename and new runtime settings creation were successful
          }

          console.log(`Runtime settings updated for renamed profile from "${oldName}" to "${newName}"`);
        } catch (runtimeError) {
          console.warn(`No runtime settings found for profile "${oldName}" or failed to update:`, runtimeError);
          // Don't throw an error here, as the profile rename was successful
          // and there might not be any runtime settings for this profile yet
        }
      } catch (error) {
        console.error('Failed to save profiles to API:', error);
        throw new Error('Failed to save profiles to MongoDB');
      }

      setProfiles(updatedProfiles);

      // If the renamed profile is the current one, update the currentProfileName
      if (currentProfileName === oldName) {
        setCurrentProfileName(newName);
      }

      return updatedProfiles;
    }, 'Failed to rename profile. Please try again.');
  }, [withErrorHandling, profiles, currentProfileName, setProfiles, setCurrentProfileName]);

  // Function to delete a profile
  const deleteProfile = useCallback(async (name: string) => {
    await withErrorHandling(async () => {
      // Prevent deleting the last profile
      if (profiles.length <= 1) {
        throw new Error('Cannot delete the only profile. At least one profile must exist.');
      }

      // Remove the profile
      const updatedProfiles = profiles.filter(profile => profile.name !== name);

      // If the deleted profile is the current one, prepare to switch to another profile
      const newCurrentProfileName = currentProfileName === name ? updatedProfiles[0].name : currentProfileName;
      const newCurrentProfileConfig = currentProfileName === name ? updatedProfiles[0].config : config;

      // Save to MongoDB
      const userId = await getCurrentUserId();
      try {
        await axios.post(`/api/profiles/${userId}`, {
          profiles: updatedProfiles,
          currentProfileName: newCurrentProfileName
        });
      } catch (error) {
        console.error('Failed to save profiles to API:', error);
        throw new Error('Failed to save profiles to MongoDB');
      }

      setProfiles(updatedProfiles);

      // If the deleted profile is the current one, switch to another profile
      if (currentProfileName === name) {
        setCurrentProfileName(newCurrentProfileName);
        setConfig(newCurrentProfileConfig);
      }

      return updatedProfiles;
    }, 'Failed to delete profile. Please try again.');
  }, [withErrorHandling, profiles, currentProfileName, config, setProfiles, setCurrentProfileName, setConfig]);

  // Load the configuration when the component mounts
  useEffect(() => {
    // Create a flag to track if the component is mounted
    let isMounted = true;

    // Call refreshConfig and handle the Promise
    refreshConfig().then(() => {
      // Only update state if the component is still mounted
      if (isMounted) {
        // No additional action needed as refreshConfig already updates the state
      }
    }).catch(err => {
      // Only update state if the component is still mounted
      if (isMounted) {
        console.error('Error in refreshConfig:', err);
      }
    });

    // Cleanup function to handle component unmounting
    return () => {
      isMounted = false;
    };
  }, [refreshConfig]);

  // Function to load configuration from the backend
  const loadConfigFromBackend = useCallback(async (connectionConfig: any) => {
    await withErrorHandling(async () => {
      if (!connectionConfig.backend_url) {
        throw new Error('No backend URL configured');
      }

      // Prepare authentication parameters for the proxy
      const { authType, authValue } = prepareAuthParams(connectionConfig);

      // Use the proxy endpoint to make the request server-side
      const proxyUrl = new URL('/proxy/config/load', getProxyOrigin());
      proxyUrl.searchParams.append('url', connectionConfig.backend_url);

      if (authType && authValue) {
        proxyUrl.searchParams.append('authType', authType);
        proxyUrl.searchParams.append('authValue', authValue);
      }

      const response = await authenticatedFetch(proxyUrl.toString(), {
        method: 'GET',
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({ error: response.statusText }));

        // Extract detailed error information
        let errorMessage = errorData.error || response.statusText;
        let errorDetails = '';

        // Check for detailed error information from our enhanced proxy
        if (errorData.details) {
          errorDetails = errorData.details;
        } else if (errorData.code) {
          errorDetails = `Error code: ${errorData.code}`;
        }

        // Check for error information in the result field
        if (errorData.result && typeof errorData.result === 'object') {
          if (errorData.result.error) {
            errorDetails += errorDetails ? `, ${errorData.result.error}` : errorData.result.error;
          } else if (typeof errorData.result === 'string') {
            errorDetails += errorDetails ? `, ${errorData.result}` : errorData.result;
          } else if (JSON.stringify(errorData.result) !== '{}') {
            errorDetails += errorDetails ? `, ${JSON.stringify(errorData.result)}` : JSON.stringify(errorData.result);
          }
        }

        // Construct a comprehensive error message
        const fullErrorMessage = errorDetails 
          ? `Failed to load configuration from backend: ${errorMessage} (${errorDetails})`
          : `Failed to load configuration from backend: ${errorMessage}`;

        console.error('Configuration loading error:', errorData);
        throw new Error(fullErrorMessage);
      }

      const data = await response.json();

      if (!data.result) {
        throw new Error('Invalid response from backend');
      }

      // Parse the configuration
      let newConfig: NauthilusConfig;

      // If the result is a string (YAML), parse it
      if (typeof data.result === 'string') {
        newConfig = yaml.load(data.result) as NauthilusConfig;
      }
      // If the result is already an object, use it directly
      else if (typeof data.result === 'object') {
        newConfig = data.result as NauthilusConfig;
      }
      else {
        throw new Error('Unexpected response format');
      }

      try {
        // Filter out unknown settings
        newConfig = filterUnknownSettings(newConfig);

        // Initialize feature configurations
        newConfig = initializeFeatureConfigurations(newConfig);

        // Bridge: map server.timeouts.ldap_* into ldap.config.* operation timeouts when missing
        if (newConfig.server?.timeouts && newConfig.ldap?.config) {
          const t = newConfig.server.timeouts as any;
          const lc = newConfig.ldap.config as any;
          if (t.ldap_search && !lc.search_timeout) {
            lc.search_timeout = t.ldap_search;
          }
          if (t.ldap_bind && !lc.bind_timeout) {
            lc.bind_timeout = t.ldap_bind;
          }
          if (t.ldap_modify && !lc.modify_timeout) {
            lc.modify_timeout = t.ldap_modify;
          }
        }

        // Check for custom hooks in the loaded configuration
        if (newConfig.lua?.custom_hooks && newConfig.lua?.custom_hooks.length > 0) {
          console.log('Found custom hooks in loaded configuration:', newConfig.lua?.custom_hooks);

          // Initialize lua and hooks objects if they don't exist
          if (!newConfig.lua) {
            newConfig.lua = {};
          }
          if (!newConfig.lua.hooks) {
            newConfig.lua.hooks = {};
          }

          // Map script filenames to hook names
          const scriptToHookMap: Record<string, keyof LuaHooksConfig> = {
            'distributed-brute-force-admin.lua': 'distributed_brute_force_admin',
            'distributed-brute-force-test.lua': 'distributed_brute_force_test'
          };

          // Check each custom hook
          newConfig.lua?.custom_hooks?.forEach(customHook => {
            // Extract the script filename from the path
            const scriptPath = customHook.script_path;
            const scriptName = scriptPath.split('/').pop();

            if (scriptName && scriptToHookMap[scriptName]) {
              const hookName = scriptToHookMap[scriptName];
              console.log(`Found matching hook: ${scriptName} -> ${hookName}`);

              // Get the current hook configuration if it exists
              const currentHook = config?.lua?.hooks?.[hookName];
              const newHook = newConfig.lua?.hooks?.[hookName];

              // Create or update the hook configuration
              if (newConfig.lua && newConfig.lua.hooks) {
                // If the hook already exists in the current config, preserve its enabled state
                if (currentHook) {
                  newConfig.lua.hooks[hookName] = {
                    ...newHook,
                    endpoint_path: newHook?.endpoint_path || '',
                    enabled: currentHook.enabled
                  };
                } else {
                  // If the hook doesn't exist in the current config or is not properly configured,
                  // create it and enable it since it's defined in custom_hooks
                  const httpLocation = customHook.http_location || '';
                  newConfig.lua.hooks[hookName] = {
                    enabled: true,
                    endpoint_path: httpLocation
                  };
                  console.log(`Enabled hook ${hookName} with endpoint ${httpLocation}`);
                }
              }
            }
          });
        }

        // Preserve the enabled state of hooks if they exist in the current configuration
        if (config?.lua?.hooks && newConfig.lua?.hooks) {
          // For each hook in the new config that also exists in the current config
          Object.keys(newConfig.lua?.hooks).forEach(hookName => {
            const typedHookName = hookName as keyof LuaHooksConfig;
            const currentHook = config?.lua?.hooks?.[typedHookName];
            const newHook = newConfig.lua?.hooks?.[typedHookName];

            if (currentHook && newHook) {
              // Preserve the enabled state from the current config
              if (newConfig.lua && newConfig.lua.hooks) {
                newConfig.lua.hooks[typedHookName] = {
                  ...newHook,
                  endpoint_path: newHook?.endpoint_path || '',
                  enabled: currentHook.enabled
                };
              }
            }
          });
        }

        // Update the current profile with the new configuration
        const updated = await updateProfilesWithConfig(newConfig);

        // Additionally, sync runtime collection hooks.custom_hooks right after loading configuration
        try {
          const userId = await getCurrentUserId();
          const runtimeUrl = `/api/runtime/${userId}/${currentProfileName}`;
          const newCustomHooks = newConfig.lua?.custom_hooks || [];

          try {
            // Fetch existing runtime settings to preserve ALL user/runtime data
            const rt = await axios.get(runtimeUrl);
            const existing = rt?.data || {};

            // Merge: keep everything, only update hooks.custom_hooks
            const merged = {
              ...existing,
              hooks: {
                ...(existing.hooks || {}),
                custom_hooks: newCustomHooks,
              },
            };

            await axios.post(runtimeUrl, merged);
            console.log('Runtime hooks synchronized from loaded configuration (merged, preserved user settings)');
          } catch (rtErr) {
            // If fetching runtime fails, create minimal doc with just custom_hooks (non-destructive since no prior doc)
            await axios.post(runtimeUrl, {
              hooks: { custom_hooks: newCustomHooks },
            });
            console.warn('Runtime GET failed; created runtime with custom_hooks only');
          }
        } catch (syncErr) {
          console.warn('Failed to sync runtime hooks after loading configuration:', syncErr);
        }

        return updated;
      } catch (error) {
        console.error('Error parsing configuration:', error);
        throw new Error(`Failed to parse configuration: ${error instanceof Error ? error.message : String(error)}`);
      }
    }, 'Failed to load configuration from backend. Please try again.');
  }, [withErrorHandling, config?.lua?.hooks, updateProfilesWithConfig]);

  // Provide the context value
  const contextValue: ConfigContextType = {
    config,
    loading,
    error,
    hasUnsavedChanges,
    profiles,
    currentProfileName,
    refreshConfig,
    updateConfig,
    updateConfigSection,
    uploadConfig,
    downloadConfig,
    resetConfig,
    loadConfigFromBackend,
    setHasUnsavedChanges,
    setError,
    validateConfigSection,
    createProfile,
    switchProfile,
    renameProfile,
    deleteProfile,
  };

  return (
    <ConfigContext.Provider value={contextValue}>
      {children}
    </ConfigContext.Provider>
  );
};

// Custom hook to use the config context
export const useConfig = (): ConfigContextType => {
  const context = useContext(ConfigContext);
  if (context === undefined) {
    throw new Error('useConfig must be used within a ConfigProvider');
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback, useMemo } from 'react';
import * as userManager from '../utils/userManager';

// Define the user type
interface User {
  username: string;
  roles: string[];
  displayName?: string;
  email?: string;
  avatar?: string;
  enabled?: boolean;
  lastLogin?: string | null;
  lastModified?: string;
  // TOTP fields
  totpEnabled?: boolean;
  totpSecret?: string;
  // WebAuthn fields
  webAuthnEnabled?: boolean;
  webAuthnDevices?: userManager.WebAuthnCredential[];
}

// Define the context type
interface UserContextType {
  isAuthenticated: boolean;
  user: User | null;
  loading: boolean;
  error: string | null;
  login: (username: string, password: string) => Promise<User | null>;
  loginAfterMfa: (username: string) => Promise<User | null>;
  logout: () => Promise<void>;
  addUser: (username: string, password: string, roles: string[]) => Promise<void>;
  removeUser: (username: string) => Promise<void>;
  getUsers: () => Promise<User[]>;
  updatePassword: (username: string, password: string) => Promise<void>;
  updateUserProfile: (username: string, profileData: Partial<Omit<User, 'username'>>) => Promise<void>;
  clearError: () => void;
}

// Create the context with a default value
const UserContext = createContext<UserContextType | undefined>(undefined);

// Provider component
interface UserProviderProps {
  children: ReactNode;
}

export const UserProvider = ({ children }: UserProviderProps): React.JSX.Element => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [user, setUser] = useState<{ username: string; roles: string[] } | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Initialize the user state
  useEffect(() => {
    // Skip initial auth check on public auth routes to avoid 401 spam on Login/MFA pages
    const pathname = typeof window !== 'undefined' ? window.location.pathname : '';
    const isPublicAuthPath = pathname === '/login' || pathname === '/mfa' || pathname === '/oidc/callback' || pathname === '/oidc/callback/';

    // Prevent duplicate checks in React StrictMode (DEV)
    const hasRun = typeof window !== 'undefined' ? (window as any).__userInitRan : false;
    if (hasRun) {
      return;
    }
    if (typeof window !== 'undefined') {
      (window as any).__userInitRan = true;
    }

    const checkAuth = async () => {
      try {
        if (isPublicAuthPath) {
          // On login/MFA/OIDC pages, do not ping /api/auth/me pre-auth
          setIsAuthenticated(false);
          setUser(null);
          return;
        }

        const authenticated = await userManager.isAuthenticated();
        setIsAuthenticated(authenticated);

        if (authenticated) {
          const currentUser = await userManager.getCurrentUser();
          setUser(currentUser);
        }
      } catch (err) {
        console.error('Error checking authentication:', err);
        setError('Failed to check authentication status');
      } finally {
        setLoading(false);
      }
    };

    (async () => {
      await checkAuth();
    })();
  }, []);

  // Login function (stable)
  const login = useCallback(async (username: string, password: string): Promise<User | null> => {
    setLoading(true);
    setError(null);

    try {
      const result = await userManager.authenticate(username, password);

      if (result) {
        setIsAuthenticated(true);
        const currentUser = await userManager.getCurrentUser();
        setUser(currentUser);
        return currentUser;
      } else {
        setError('Invalid username or password');
        return null;
      }
    } catch (err) {
      console.error('Login error:', err);
      setError('An error occurred during login');
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  // Login after MFA completion function (stable)
  const loginAfterMfa = useCallback(async (username: string): Promise<User | null> => {
    setLoading(true);
    setError(null);

    try {
      // Skip authentication since it's already done in AuthContext
      // Just update the user state with the current user
      setIsAuthenticated(true);
      const currentUser = await userManager.getCurrentUser();

      if (currentUser) {
        console.log('UserContext: Setting user after MFA completion:', currentUser);
        setUser(currentUser);
        return currentUser;
      } else {
        console.error('UserContext: Failed to get current user after MFA completion');
        setError('Failed to get user information after MFA');
        return null;
      }
    } catch (err) {
      console.error('UserContext: Error in loginAfterMfa:', err);
      setError('An error occurred during login after MFA');
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  // Logout function (stable)
  const logout = useCallback(async (): Promise<void> => {
    setLoading(true);

    try {
      await userManager.logout();
      setIsAuthenticated(false);
      setUser(null);
    } catch (err) {
      console.error('Logout error:', err);
      setError('An error occurred during logout');
    } finally {
      setLoading(false);
    }
  }, []);

  // Add user function (stable)
  const addUser = useCallback(async (username: string, password: string, roles: string[]): Promise<void> => {
    setLoading(true);
    setError(null);

    try {
      await userManager.addUser(username, password, roles);
    } catch (err) {
      console.error('Add user error:', err);
      setError('An error occurred while adding the user');
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  // Remove user function (stable)
  const removeUser = useCallback(async (username: string): Promise<void> => {
    setLoading(true);
    setError(null);

    try {
      await userManager.removeUser(username);
    } catch (err) {
      console.error('Remove user error:', err);
      setError('An error occurred while removing the user');
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  // Get users function (stable)
  const getUsers = useCallback(async (): Promise<User[]> => {
    setLoading(true);
    setError(null);

    try {
      return await userManager.getUsers();
    } catch (err) {
      console.error('Get users error:', err);
      setError('An error occurred while getting users');
      return [];
    } finally {
      setLoading(false);
    }
  }, []);

  // Update password function (stable)
  const updatePassword = useCallback(async (username: string, password: string): Promise<void> => {
    setLoading(true);
    setError(null);

    try {
      // Get current user to preserve all user data
      const users = await userManager.getUsers();
      const userToUpdate = users.find(u => u.username === username);

      if (userToUpdate) {
        // Extract profile data to preserve
        const { displayName, email, avatar, lastLogin, lastModified } = userToUpdate;
        const profileData = { displayName, email, avatar, lastLogin, lastModified };

        // Update user with preserved profile data
        await userManager.addUser(username, password, userToUpdate.roles, profileData);
      } else {
        console.error('User not found');
        return;
      }
    } catch (err) {
      console.error('Update password error:', err);
      setError('An error occurred while updating the password');
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  // Update user profile function (stable)
  const updateUserProfile = useCallback(async (username: string, profileData: Partial<Omit<User, 'username'>>): Promise<void> => {
    setLoading(true);
    setError(null);

    try {
      // Get the current user to preserve roles and other data
      const users = await userManager.getUsers();
      const userToUpdate = users.find(u => u.username === username);

      if (userToUpdate) {
        // Create a copy of the profile data
        const updatedProfileData = {
          ...profileData
        };

        // Check if we're only updating lastLogin
        const isOnlyLastLoginUpdate = Object.keys(profileData).length === 1 && 'lastLogin' in profileData;

        // If we're not just updating lastLogin, check if there are actual changes
        if (!isOnlyLastLoginUpdate) {
          // Check if there are actual changes to the profile
          let hasChanges = false;

          // Compare each field in profileData with the current user data
          for (const key in profileData) {
            if (key !== 'lastLogin' && key !== 'lastModified') {
              // Handle undefined values correctly
              const newValue = profileData[key as keyof typeof profileData];
              const currentValue = userToUpdate[key as keyof typeof userToUpdate];

              // Check if the values are different
              if ((newValue || '') !== (currentValue || '')) {
                hasChanges = true;
                break;
              }
            }
          }

          // Only update lastModified if there are actual changes
          if (hasChanges) {
            updatedProfileData.lastModified = new Date().toISOString();
          } else {
            // No changes, preserve the existing lastModified value
            updatedProfileData.lastModified = userToUpdate.lastModified;
          }
        } else {
          // For lastLogin updates, preserve the existing lastModified value
          updatedProfileData.lastModified = userToUpdate.lastModified;
        }

        await userManager.updateUserProfile(username, updatedProfileData);

        // If the current user is being updated, refresh the user state
        if (user && user.username === username) {
          const currentUser = await userManager.getCurrentUser();
          setUser(currentUser);
        }
      } else {
        console.error('User not found');
        return;
      }
    } catch (err) {
      console.error('Update user profile error:', err);
      setError('An error occurred while updating the user profile');
      throw err;
    } finally {
      setLoading(false);
    }
  }, [user]);

  // Clear error function (stable)
  const clearError = useCallback((): void => {
    setError(null);
  }, []);

  // Provide the context value
  const contextValue: UserContextType = useMemo(() => ({
    isAuthenticated,
    user,
    loading,
    error,
    login,
    loginAfterMfa,
    logout,
    addUser,
    removeUser,
    getUsers,
    updatePassword,
    updateUserProfile,
    clearError
  }), [isAuthenticated, user, loading, error, login, loginAfterMfa, logout, addUser, removeUser, getUsers, updatePassword, updateUserProfile, clearError]);

  return (
    <UserContext.Provider value={contextValue}>
      {children}
    </UserContext.Provider>
  );
};

// Custom hook to use the user context
export const useUser = (): UserContextType => {
  const context = useContext(UserContext);
  if (context === undefined) {
    throw new Error('useUser must be used within a UserProvider');
  }
  return context;
};

import {useState} from "react";
import {InitialHookStatus} from "@react-buddy/ide-toolbox";

export const useInitial: () => InitialHookStatus = () => {
    const [status, setStatus] = useState<InitialHookStatus>({
        loading: false,
        error: false,
    });
    /*
      Implement hook functionality here.
      If you need to execute async operation, set loading to true and when it's over, set loading to false.
      If you caught some errors, set error status to true.
      Initial hook is considered to be successfully completed if it will return {loading: false, error: false}.
    */
    return status;
};

/**
 * Utility functions for API operations
 */
import Cookies from 'js-cookie';

/**
 * Retrieves the proxy origin URL based on the current environment configuration.
 *
 * The function checks the following sources in order of priority:
 * 1. `window._env_?.REACT_APP_PROXY_PORT` - If available, this port value is used.
 * 2. `process.env.REACT_APP_PROXY_PORT` - If running in a Node.js-like environment, this port value is used.
 * 3. Fallback to the default port `3002` if neither of the above are defined.
 *
 * A debug message is logged for each source used to determine the port.
 *
 * @returns {string} The generated proxy origin URL based on the chosen port.
 */
export const getProxyOrigin = (): string => {
  if (window._env_?.REACT_APP_PROXY_PORT) {
    console.debug('[getProxyOrigin] Source: window._env_, Port:', window._env_.REACT_APP_PROXY_PORT);
    return buildUrl(window._env_.REACT_APP_PROXY_PORT);
  }

  if (typeof process !== 'undefined' && process.env.REACT_APP_PROXY_PORT) {
    console.debug('[getProxyOrigin] Source: process.env, Port:', process.env.REACT_APP_PROXY_PORT);
    return buildUrl(process.env.REACT_APP_PROXY_PORT);
  }

  console.debug('[getProxyOrigin] Source: Fallback, Port: 3002');
  return buildUrl('3002');
};

/**
 * Constructs a URL based on the provided port and current window location details.
 *
 * @param {string} port - The port to use when building the URL. If the port is "443" and the protocol is "https:", the port is omitted from the URL.
 * @return {string} The constructed URL as a string.
 */
function buildUrl(port: string): string {
  const { protocol, hostname } = window.location;
  return port === '443' && protocol === 'https:'
      ? `${protocol}//${hostname}`
      : `${protocol}//${hostname}:${port}`;
}

/**
 * Gets the current JWT token from cookies
 * @returns The JWT token or null if not found
 */
export const getAuthToken = (): string | null => {
  // Get token from cookie (TOKEN_COOKIE_NAME from userManager.ts is 'nauthilus_token')
  const token = Cookies.get('nauthilus_token');

  return token || null;
};

/**
 * Prepares authentication parameters for API requests
 * @param connectionConfig - The connection configuration object containing auth settings
 * @returns An object with authType and authValue properties
 */
export const prepareAuthParams = (connectionConfig: any): { authType: string, authValue: string } => {
  let authType = '';
  let authValue = '';

  // Add Basic Auth if enabled
  if (connectionConfig.basic_auth?.enabled && 
      connectionConfig.basic_auth.username && 
      connectionConfig.basic_auth.password) {
    authType = 'basic';
    authValue = btoa(`${connectionConfig.basic_auth.username}:${connectionConfig.basic_auth.password}`);
  }

  // For JWT Auth, use existing token if available
  if (connectionConfig.jwt_auth?.enabled && connectionConfig.jwt_auth.token) {
    authType = 'bearer';
    authValue = connectionConfig.jwt_auth.token;
  }

  return { authType, authValue };
};

/**
 * Extracts a detailed error message from an API response
 * @param response - The Response object from a fetch request
 * @returns A formatted error message string
 */
export const extractErrorMessage = async (response: Response): Promise<string> => {
  const errorData = await response.json().catch(() => ({ error: response.statusText }));

  // Extract more detailed error information if available
  let errorMessage = errorData.error || response.statusText;

  // Add HTTP status code to the error message
  errorMessage = `[${response.status} ${response.statusText}] ${errorMessage}`;

  // Check if there are detailed error information fields
  if (errorData.details) {
    errorMessage = `${errorMessage}: ${errorData.details}`;
  } else if (errorData.code) {
    errorMessage = `${errorMessage} (Code: ${errorData.code})`;
  }

  // Check if there's a more detailed error message in the result field
  if (errorData.result && typeof errorData.result === 'object') {
    if (errorData.result.error) {
      errorMessage = `${errorMessage}: ${errorData.result.error}`;
    } else if (typeof errorData.result === 'string') {
      errorMessage = `${errorMessage}: ${errorData.result}`;
    } else if (JSON.stringify(errorData.result) !== '{}') {
      errorMessage = `${errorMessage}: ${JSON.stringify(errorData.result)}`;
    }
  }

  return errorMessage;
};

/**
 * Checks connection to the backend
 * @param connectionConfig - The connection configuration object
 * @param setConnectionStatus - Function to set the connection status
 * @param setStatusMessage - Function to set the status message
 */
export const checkConnection = async (
  connectionConfig: any,
  setConnectionStatus: (status: 'unknown' | 'connected' | 'disconnected' | 'checking') => void,
  setStatusMessage: (message: string) => void
) => {
  if (!connectionConfig.backend_url) {
    // Treat missing URL as a disconnected state to avoid lingering "Not checked"
    setConnectionStatus('disconnected');
    setStatusMessage('No backend URL configured');
    return;
  }

  setConnectionStatus('checking');
  setStatusMessage('Checking connection...');

  try {
    // Use the proxy endpoint to make the request server-side
    const proxyUrl = new URL('/proxy/ping', getProxyOrigin());
    proxyUrl.searchParams.append('url', connectionConfig.backend_url);

    // Use the authenticatedFetch helper
    const response = await authenticatedFetch(proxyUrl.toString(), {
      method: 'GET',
    });

    if (response.ok) {
      setConnectionStatus('connected');
      setStatusMessage('Connected to Nauthilus backend (ping successful)');
    } else {
      setConnectionStatus('disconnected');
      const errorMessage = await extractErrorMessage(response);
      setStatusMessage(`Failed to connect: ${errorMessage}`);
    }
  } catch (error) {
    console.error('Error checking connection:', error);
    setConnectionStatus('disconnected');
    setStatusMessage(`Connection error: ${error instanceof Error ? error.message : String(error)}`);
  }
};

/**
 * Helper function to wrap operations with error handling
 * @param setLoading - Function to set loading state
 * @param setError - Function to set error state
 * @param operation - The operation to execute
 * @param errorMessage - Error message to display if operation fails
 * @returns The result of the operation or undefined if it fails
 */
export const withErrorHandling = async <T,>(
  setLoading: (loading: boolean) => void,
  setError: (error: string | null) => void,
  operation: () => Promise<T> | T,
  errorMessage: string
): Promise<T | undefined> => {
  try {
    setLoading(true);
    setError(null);
    return await operation();
  } catch (err) {
    setError(errorMessage);
    console.error(`${errorMessage}:`, err);
    return undefined;
  } finally {
    setLoading(false);
  }
};

/**
 * Resets the settings state to force a reload on the next call to loadSettings
 */
export const resetSettingsState = () => {
  if (window.__settingsState) {
    window.__settingsState.loaded = false;
  }
  console.log('Settings state reset, next call to loadSettings will reload settings');
};

/**
 * Performs an authenticated fetch request with JWT token and robust 401 handling
 * - Adds Authorization header from cookie token when present
 * - Sends credentials to proxy
 * - On 401, performs a single-flight refresh and retries the request once
 */

// Single-flight refresh state for fetch-based requests
let isRefreshingFetch = false;
let waitersFetch: Array<(ok: boolean) => void> = [];

async function refreshSessionFetch(): Promise<boolean> {
  try {
    const resp = await fetch(`${getProxyOrigin()}/api/auth/refresh`, {
      method: 'POST',
      credentials: 'include'
    });
    return resp.ok;
  } catch {
    return false;
  }
}

function waitForRefresh(): Promise<boolean> {
  return new Promise((resolve) => waitersFetch.push(resolve));
}

function isAuthEndpoint(url: string): boolean {
  return (
    url.includes('/api/auth/login') ||
    url.includes('/api/auth/refresh') ||
    url.includes('/api/auth/logout') ||
    url.includes('/api/auth/me') ||
    url.includes('/api/auth/webauthn/') ||
    url.includes('/api/auth/totp/')
  );
}

export const authenticatedFetch = async (
  url: string,
  options: RequestInit = {}
): Promise<Response> => {
  // Get the JWT token
  const token = getAuthToken();

  // Prepare headers
  const headers = new Headers(options.headers || {});

  // Decide whether to set a default Content-Type
  const method = (options.method || 'GET').toUpperCase();
  const hasBody = options.body !== undefined && options.body !== null;
  const isFormData = typeof FormData !== 'undefined' && hasBody && (options.body as any) instanceof FormData;

  if (hasBody && !isFormData && !headers.has('Content-Type') && method !== 'GET' && method !== 'HEAD') {
    headers.set('Content-Type', 'application/json');
  }

  // Add Authorization header if token exists
  if (token && !headers.has('Authorization')) {
    headers.set('Authorization', `Bearer ${token}`);
  }

  // Merge options with headers
  const fetchOptions: RequestInit = {
    ...options,
    headers,
    credentials: 'include'
  };

  async function doFetchOnce(): Promise<Response> {
    return fetch(url, fetchOptions);
  }

  let response = await doFetchOnce();
  if (response.status !== 401) {
    return response;
  }

  // Don't attempt refresh for auth endpoints themselves
  if (isAuthEndpoint(url)) {
    return response;
  }

  if (!isRefreshingFetch) {
    isRefreshingFetch = true;
    try {
      const ok = await refreshSessionFetch();
      // Wake up waiters
      waitersFetch.forEach((fn) => fn(ok));
      waitersFetch = [];

      if (ok) {
        // Retry once
        response = await doFetchOnce();
        if (response.status === 401) {
          try {
            const { notifySessionExpired } = await import('./notify');
            notifySessionExpired('Your session has expired. Please sign in again.');
          } catch {
            // eslint-disable-next-line no-alert
            window.alert('Your session has expired. Please sign in again.');
          }
        }
        return response;
      }

      // Refresh failed
      try {
        const { notifySessionExpired } = await import('./notify');
        notifySessionExpired('Your session has expired. Please sign in again.');
      } catch {
        // eslint-disable-next-line no-alert
        window.alert('Your session has expired. Please sign in again.');
      }
      return response;
    } finally {
      isRefreshingFetch = false;
    }
  }

  // Another refresh is in progress – wait and retry once if it succeeded
  const ok = await waitForRefresh();
  if (ok) {
    return doFetchOnce();
  }
  return response;
};

/**
 * Sends HTML to the backend to generate a server-side PDF and returns the Blob.
 */
export const generatePDFServerSide = async (html: string, filename?: string): Promise<Blob> => {
  const res = await authenticatedFetch('/api/report/pdf', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ html, filename })
  });
  if (!res.ok) {
    const msg = await extractErrorMessage(res).catch(async () => `${res.status} ${res.statusText}`);
    throw new Error(msg);
  }
  return await res.blob();
};

/**
 * Loads runtime settings and checks connection status
 * @param getCurrentUserId - Function to get the current user ID
 * @param loadRuntimeSettings - Function to load runtime settings
 * @param currentProfileName - Current profile name
 * @param checkConnection - Function to check connection status
 * @param getConnection - Function to get the current connection configuration
 */
export const loadSettings = async (
  getCurrentUserId: () => Promise<string>,
  loadRuntimeSettings: (userId: string, profileName: string) => Promise<void>,
  currentProfileName: string,
  checkConnection: (connectionConfig: any) => Promise<void>,
  getConnection: () => any
) => {
  try {
    // Get current connection data (may be empty on first render)
    const currentConnection = getConnection();
    const currentConnectionUrl = currentConnection?.backend_url || '';

    // Initialize settings state singleton on window
    if (!window.__settingsState) {
      window.__settingsState = {
        loaded: false,
        profileName: '',
        connectionUrl: '',
        lastCheckedUrl: '',
        lastCheckedAt: 0,
        inFlightKey: '',
        inFlightPromise: undefined as Promise<void> | undefined,
      } as any;
    }

    const state: any = window.__settingsState!;

    // Helper: decide whether we should run a connection check right now
    const shouldCheckNow = (url: string): boolean => {
      if (!url) return false; // nothing to check
      // Avoid immediate repeats (e.g., React StrictMode double effects in DEV)
      const now = Date.now();
      const lastUrl = state.lastCheckedUrl || '';
      const lastAt = state.lastCheckedAt || 0;
      const isSameUrl = lastUrl === url;
      const withinDebounce = now - lastAt < 1500; // 1.5s debounce window
      return !(isSameUrl && withinDebounce);
    };

    // Compute a key for the current desired load
    const desiredKey = `${currentProfileName}|${currentConnectionUrl}`;

    // If a matching load is already in-flight, await it instead of starting another
    if (state.inFlightPromise && state.inFlightKey === desiredKey) {
      await state.inFlightPromise;
      // After in-flight finishes, do a debounced ping if needed and exit
      if (shouldCheckNow(currentConnectionUrl)) {
        await checkConnection(getConnection());
        state.lastCheckedUrl = currentConnectionUrl;
        state.lastCheckedAt = Date.now();
      }
      return;
    }

    // Check if we actually need to reload
    const needsReload = !state.loaded ||
      state.profileName !== currentProfileName ||
      state.connectionUrl !== currentConnectionUrl;

    if (!needsReload) {
      // Already up-to-date, just do a debounced connection check
      if (shouldCheckNow(currentConnectionUrl)) {
        await checkConnection(currentConnection);
        state.lastCheckedUrl = currentConnectionUrl;
        state.lastCheckedAt = Date.now();
      }
      return;
    }

    // Start a new in-flight load for this key
    state.inFlightKey = desiredKey;
    state.inFlightPromise = (async () => {
      console.log(`Loading settings for profile: ${currentProfileName}, preload connection: ${currentConnectionUrl || '(none)'}`);
      const userId = await getCurrentUserId();
      await loadRuntimeSettings(userId, currentProfileName);

      // Give React state a tick to propagate (RuntimeContext updates connection asynchronously)
      await new Promise(resolve => setTimeout(resolve, 0));

      // After load, re-read connection and ping (debounced)
      const connectionToCheck = getConnection();
      const urlToCheck = connectionToCheck?.backend_url || '';
      console.log(`Runtime settings loaded for profile: ${currentProfileName}, effective connection: ${urlToCheck || '(none)'}`);
      if (shouldCheckNow(urlToCheck)) {
        await checkConnection(connectionToCheck);
        state.lastCheckedUrl = urlToCheck;
        state.lastCheckedAt = Date.now();
      }

      // Mark as loaded
      state.loaded = true;
      state.profileName = currentProfileName;
      state.connectionUrl = urlToCheck;
    })();

    try {
      await state.inFlightPromise;
    } finally {
      // Clear in-flight markers only if they correspond to this key
      if (state.inFlightKey === desiredKey) {
        state.inFlightPromise = undefined;
        state.inFlightKey = '';
      }
    }
  } catch (error) {
    console.error('Failed to load runtime settings:', error);
  }
};

import axios from 'axios';
import { getAuthToken, getProxyOrigin } from './apiUtils';

// Configure axios defaults
axios.defaults.withCredentials = true;

// Add a request interceptor to include JWT token in all requests
axios.interceptors.request.use(
  (config) => {
    // Skip adding token for unauthenticated auth endpoints
    if (
      config.url && (
        config.url.includes('/api/auth/login') ||
        config.url.includes('/api/auth/refresh') ||
        config.url.includes('/api/auth/logout') ||
        config.url.includes('/api/auth/webauthn/') ||
        config.url.includes('/api/auth/totp/')
      )
    ) {
      return config;
    }

    const token = getAuthToken();
    if (token) {
      (config.headers as any).Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Global 401 handling with one-time refresh and retry
let isRefreshing = false;
let pendingResolvers: Array<(ok: boolean) => void> = [];

async function refreshSession(): Promise<boolean> {
  try {
    // Use relative URL to ensure cookies for the current origin are sent reliably in dev/prod
    await axios.post('/api/auth/refresh', {}, { withCredentials: true });
    return true;
  } catch {
    return false;
  }
}

axios.interceptors.response.use(
  (response) => response,
  async (error) => {
    const { response, config } = error || {};
    const originalRequest = config || {};

    if (!response || response.status !== 401) {
      return Promise.reject(error);
    }

    const url: string = (originalRequest && originalRequest.url) || '';
    if (
      !url ||
      url.includes('/api/auth/login') ||
      url.includes('/api/auth/refresh') ||
      url.includes('/api/auth/logout')
    ) {
      // Do not attempt refresh for auth endpoints themselves
      return Promise.reject(error);
    }

    if (!isRefreshing) {
      isRefreshing = true;
      try {
        const ok = await refreshSession();
        pendingResolvers.forEach((fn) => fn(ok));
        pendingResolvers = [];
        if (ok) {
          // Retry the original request
          return axios(originalRequest);
        }
        // Session expired: inform user with a unified dialog
        try {
          const { notifySessionExpired } = await import('./notify');
          notifySessionExpired('Your session has expired. Please sign in again.');
        } catch {
          // Fallback just in case dynamic import fails
          window.alert('Your session has expired. Please sign in again.');
        }
        return Promise.reject(error);
      } finally {
        isRefreshing = false;
      }
    }

    // Wait for the in-flight refresh to finish
    return new Promise((resolve, reject) => {
      pendingResolvers.push((ok) => {
        if (ok) resolve(axios(originalRequest));
        else reject(error);
      });
    });
  }
);

export default axios;

/**
 * Utility providing limits and sanity clamping for RAW JSON inputs
 */

/** Min and Max sane bounds (bytes) */
export const RAW_JSON_MIN_BYTES = 1024;     // 1 KiB
export const RAW_JSON_MAX_BYTES = 1048576;  // 1 MiB

/**
 * Parses an environment variable into a number of bytes, if possible.
 */
function parseEnvNumber(val: any): number | null {
  if (val == null) return null;
  const n = Number(val);
  return Number.isFinite(n) && n > 0 ? n : null;
}

/**
 * Returns the configured maximum number of bytes allowed for RAW JSON input.
 * 
 * Precedence:
 * - window._env_.REACT_APP_RAW_JSON_MAX_BYTES (when injected at runtime)
 * - process.env.REACT_APP_RAW_JSON_MAX_BYTES (at build-time)
 * - default: 8192 (8 KiB)
 *
 * Sanity limits: clamp to [RAW_JSON_MIN_BYTES, RAW_JSON_MAX_BYTES]
 */
export function getRawJsonMaxBytes(): number {
  const DEFAULT = 8192;    // 8 KiB

  // Prefer window._env_ when available (runtime-injected envs)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const w: any = typeof window !== 'undefined' ? (window as any) : undefined;
  let from: string | null = null;
  let rawVal: any = undefined;

  if (w && w._env_ && w._env_.REACT_APP_RAW_JSON_MAX_BYTES != null) {
    from = 'window._env_';
    rawVal = w._env_.REACT_APP_RAW_JSON_MAX_BYTES;
  } else if (typeof process !== 'undefined' && (process as any).env && (process as any).env.REACT_APP_RAW_JSON_MAX_BYTES != null) {
    from = 'process.env';
    rawVal = (process as any).env.REACT_APP_RAW_JSON_MAX_BYTES;
  }

  let configured = parseEnvNumber(rawVal);
  let value = configured ?? DEFAULT;

  if (value < RAW_JSON_MIN_BYTES) {
    console.warn(`[getRawJsonMaxBytes] Configured value too low (${value}). Clamping to ${RAW_JSON_MIN_BYTES}. Source: ${from ?? 'default'}`);
    value = RAW_JSON_MIN_BYTES;
  } else if (value > RAW_JSON_MAX_BYTES) {
    console.warn(`[getRawJsonMaxBytes] Configured value too high (${value}). Clamping to ${RAW_JSON_MAX_BYTES}. Source: ${from ?? 'default'}`);
    value = RAW_JSON_MAX_BYTES;
  }

  return value;
}

/**
 * Session override helpers (per-browser tab)
 */
const RAW_JSON_OVERRIDE_SESSION_KEY = 'ui.rawJsonMaxBytes.override';

export function getRawJsonMaxBytesOverride(): number | null {
  if (typeof sessionStorage === 'undefined') return null;
  const v = sessionStorage.getItem(RAW_JSON_OVERRIDE_SESSION_KEY);
  if (!v) return null;
  const n = Number(v);
  return Number.isFinite(n) ? Math.max(RAW_JSON_MIN_BYTES, Math.min(RAW_JSON_MAX_BYTES, n)) : null;
}

export function setRawJsonMaxBytesOverride(val: number | null): void {
  if (typeof sessionStorage === 'undefined') return;
  if (val == null) {
    sessionStorage.removeItem(RAW_JSON_OVERRIDE_SESSION_KEY);
    return;
  }
  const clamped = Math.max(RAW_JSON_MIN_BYTES, Math.min(RAW_JSON_MAX_BYTES, Number(val)));
  sessionStorage.setItem(RAW_JSON_OVERRIDE_SESSION_KEY, String(clamped));
}

export function getEffectiveRawJsonMaxBytes(): number {
  return getRawJsonMaxBytesOverride() ?? getRawJsonMaxBytes();
}

/**
 * Returns the UTF-8 byte length of a string.
 */
export function byteLengthUtf8(str: string): number {
  if (typeof TextEncoder !== 'undefined') {
    return new TextEncoder().encode(str).length;
  }
  // Fallback: approximate via encodeURIComponent (slightly larger but safe upper bound)
  try {
    return unescape(encodeURIComponent(str)).length;
  } catch {
    return str.length; // last-resort fallback
  }
}

/**
 * Truncate a large string to a byte limit and return a user-facing banner + content, consistent across pages.
 * The limit is clamped into [RAW_JSON_MIN_BYTES, RAW_JSON_MAX_BYTES].
 */
export function applyPreviewLimit(full: string, limit: number): string {
  const MAX_PREVIEW = Math.max(RAW_JSON_MIN_BYTES, Math.min(RAW_JSON_MAX_BYTES, Number.isFinite(limit) ? limit : RAW_JSON_MIN_BYTES));
  const totalBytes = byteLengthUtf8(full);
  if (totalBytes <= MAX_PREVIEW) {
    return `[Raw preview — limit ${MAX_PREVIEW} bytes — showing ${totalBytes} of ${totalBytes} bytes]\n\n${full}`;
  }
  // approximate truncation by substring while staying under byte limit
  let end = Math.floor(full.length * (MAX_PREVIEW / Math.max(1, totalBytes)));
  end = Math.max(0, Math.min(full.length, end));
  let cut = full.substring(0, end);
  while (byteLengthUtf8(cut) > MAX_PREVIEW && end > 0) {
    end -= Math.max(1, Math.floor(end * 0.05));
    cut = full.substring(0, end);
  }
  const shownBytes = byteLengthUtf8(cut);
  return `[Raw preview — limit ${MAX_PREVIEW} bytes — showing ${shownBytes} of ${totalBytes} bytes]\n\n${cut}\n\n[Note: Output too large – preview has been truncated.]`;
}

